        .unit => .unit,
    };
}

fn normalizeSlice(s: Slice, len: usize) ArrayError!struct { start: usize, stop: usize, step: usize, count: usize } {
    if (s.step <= 0) return error.InvalidShape;
    const length: isize = @intCast(len);
    var start = if (s.start < 0) length + s.start else s.start;
    var stop = if (s.stop) |v| if (v < 0) length + v else v else length;
    if (start < 0) start = 0;
    if (stop < 0) stop = 0;
    if (start > length) start = length;
    if (stop > length) stop = length;
    const u_start: usize = @intCast(start);
    const u_stop: usize = @intCast(stop);
    const u_step: usize = @intCast(s.step);
    const count = if (u_stop <= u_start) 0 else (u_stop - u_start + u_step - 1) / u_step;
    return .{ .start = u_start, .stop = u_stop, .step = u_step, .count = count };
}

fn usizeToPositiveIsize(value: usize) ArrayError!isize {
    if (value > @as(usize, @intCast(std.math.maxInt(isize)))) return error.InvalidShape;
    return @intCast(value);
}

fn inferredShape(allocator: std.mem.Allocator, dims: []const isize, element_count: usize) ArrayError![]usize {
    if (dims.len == 0) {
        if (element_count != 1) return error.ShapeMismatch;
        return allocator.alloc(usize, 0);
    }
    const out = try allocator.alloc(usize, dims.len);
    errdefer allocator.free(out);
    var inferred_axis: ?usize = null;
    var known_product: usize = 1;
    for (dims, 0..) |dim_value, i| {
        if (dim_value == -1) {
            if (inferred_axis != null) return error.InvalidShape;
            inferred_axis = i;
            out[i] = 1;
        } else if (dim_value < 0) {
            return error.InvalidShape;
        } else {
            const dim: usize = @intCast(dim_value);
            out[i] = dim;
            known_product = std.math.mul(usize, known_product, dim) catch return error.InvalidShape;
        }
    }
    if (inferred_axis) |axis| {
        if (known_product == 0 or element_count % known_product != 0) return error.ShapeMismatch;
        out[axis] = element_count / known_product;
    } else if (known_product != element_count) {
        return error.ShapeMismatch;
    }
    return out;
}

fn flattenShape(
    allocator: std.mem.Allocator,
    shape: []const usize,
    start_axis: isize,
    end_axis: isize,
) ArrayError![]usize {
    if (shape.len == 0) return error.InvalidAxis;
    const start = try normalizeDim(start_axis, shape.len);
    const end = try normalizeDim(end_axis, shape.len);
    if (start > end) return error.InvalidAxis;
    const out_rank = shape.len - (end - start);
    const out = try allocator.alloc(usize, out_rank);
    errdefer allocator.free(out);
    var write: usize = 0;
    for (shape[0..start]) |dim| {
        out[write] = dim;
        write += 1;
    }
    out[write] = product(shape[start .. end + 1]);
    write += 1;
    for (shape[end + 1 ..]) |dim| {
        out[write] = dim;
        write += 1;
    }
    return out;
}

fn unflattenShape(
    allocator: std.mem.Allocator,
    shape: []const usize,
    axis_index: isize,
    dims: []const usize,
) ArrayError![]usize {
    if (shape.len == 0) return error.InvalidAxis;
    const axis = try normalizeDim(axis_index, shape.len);
    const expanded = try numelFrom(dims);
    if (expanded != shape[axis]) return error.ShapeMismatch;
    const out = try allocator.alloc(usize, shape.len - 1 + dims.len);
    errdefer allocator.free(out);
    var write: usize = 0;
    for (shape[0..axis]) |dim| {
        out[write] = dim;
        write += 1;
    }
    for (dims) |dim| {
        out[write] = dim;
        write += 1;
    }
    for (shape[axis + 1 ..]) |dim| {
        out[write] = dim;
        write += 1;
    }
    return out;
}

fn validateStridedBounds(data_len: usize, offset: usize, dims: []const usize, stride_values: []const usize) ArrayError!void {
    if (dims.len != stride_values.len) return error.InvalidShape;
    if (offset > data_len) return error.IndexOutOfBounds;
    var empty = false;
    var max_offset = offset;
    for (dims, stride_values) |dim, stride_value| {
        if (dim == 0) {
            empty = true;
            continue;
        }
        const span = std.math.mul(usize, dim - 1, stride_value) catch return error.InvalidShape;
        max_offset = std.math.add(usize, max_offset, span) catch return error.InvalidShape;
    }
    if (empty) return;
    if (max_offset >= data_len) return error.IndexOutOfBounds;
}

fn computeStorageSpan(dims: []const usize, stride_values: []const usize) ArrayError!usize {
    if (dims.len != stride_values.len) return error.InvalidShape;
    if (dims.len == 0) return 1;
    var empty = false;
    var max_delta: usize = 0;
    for (dims, stride_values) |extent, stride_value| {
        if (extent == 0) {
            empty = true;
            continue;
        }
        const delta = std.math.mul(usize, extent - 1, stride_value) catch return error.InvalidShape;
        max_delta = std.math.add(usize, max_delta, delta) catch return error.InvalidShape;
    }
    if (empty) return 0;
    return std.math.add(usize, max_delta, 1) catch return error.InvalidShape;
}

pub const StorageRange = struct {
    begin: usize,
    end: usize,

    pub fn len(self: StorageRange) usize {
        return self.end - self.begin;
    }

    pub fn isEmpty(self: StorageRange) bool {
        return self.begin == self.end;
    }

    pub fn is_empty(self: StorageRange) bool {
        return self.isEmpty();
    }
};

fn computeStorageRange(offset: usize, dims: []const usize, stride_values: []const usize) ArrayError!StorageRange {
    const span = try computeStorageSpan(dims, stride_values);
    const end = std.math.add(usize, offset, span) catch return error.InvalidShape;
    return .{ .begin = offset, .end = end };
}

fn rangesOverlap(lhs_begin: usize, lhs_end: usize, rhs_begin: usize, rhs_end: usize) bool {
    if (lhs_begin >= lhs_end or rhs_begin >= rhs_end) return false;
    return lhs_begin < rhs_end and rhs_begin < lhs_end;
}

pub fn ArrayView(comptime T: type) type {
    return struct {
        const Self = @This();

        allocator: std.mem.Allocator,
        data: []T,
        shape: []usize,
        strides: []usize,
        offset: usize = 0,
        device: Device = .cpu,

        pub const Scalar = T;
        pub const dtype = DType.of(T);

        pub const BroadcastPair = struct {
            first: Self,
            second: Self,

            pub fn deinit(self: *@This()) void {
                self.first.deinit();
                self.second.deinit();
                self.* = undefined;
            }
        };

        pub fn dtypeName(self: Self) []const u8 {
            _ = self;
            return dtype.name();
        }

        pub fn dtype_name(self: Self) []const u8 {
            return self.dtypeName();
        }

        pub fn dtypeTag(self: Self) u8 {
            _ = self;
            return dtype.tag();
        }

        pub fn dtype_tag(self: Self) u8 {
            return self.dtypeTag();
        }

        pub fn dtypeByteSize(self: Self) usize {
            _ = self;
            return dtype.byteSize();
        }

        pub fn dtype_byte_size(self: Self) usize {
            return self.dtypeByteSize();
        }

        pub fn dtypeBitSize(self: Self) usize {
            _ = self;
            return dtype.bitSize();
        }

        pub fn dtype_bit_size(self: Self) usize {
            return self.dtypeBitSize();
        }

        pub fn isFloatDtype(self: Self) bool {
            _ = self;
            return dtype.isFloat();
        }

        pub fn is_float_dtype(self: Self) bool {
            return self.isFloatDtype();
        }

        pub fn isIntegerDtype(self: Self) bool {
            _ = self;
            return dtype.isInteger();
        }

        pub fn is_integer_dtype(self: Self) bool {
            return self.isIntegerDtype();
        }

        pub fn isSignedDtype(self: Self) bool {
            _ = self;
            return dtype.isSigned();
        }

        pub fn is_signed_dtype(self: Self) bool {
            return self.isSignedDtype();
        }

        pub fn isUnsignedDtype(self: Self) bool {
            _ = self;
            return dtype.isUnsigned();
        }

        pub fn is_unsigned_dtype(self: Self) bool {
            return self.isUnsignedDtype();
        }

        pub fn isComplexDtype(self: Self) bool {
            _ = self;
            return dtype.isComplex();
        }

        pub fn is_complex_dtype(self: Self) bool {
            return self.isComplexDtype();
        }

        pub fn isBoolDtype(self: Self) bool {
            _ = self;
            return dtype.isBool();
        }

        pub fn is_bool_dtype(self: Self) bool {
            return self.isBoolDtype();
        }

        pub fn isRealDtype(self: Self) bool {
            _ = self;
            return dtype.isReal();
        }

        pub fn is_real_dtype(self: Self) bool {
            return self.isRealDtype();
        }

        pub fn isNumericDtype(self: Self) bool {
            _ = self;
            return dtype.isNumeric();
        }

        pub fn is_numeric_dtype(self: Self) bool {
            return self.isNumericDtype();
        }

        pub fn canCastToDtype(self: Self, target: DType) bool {
            _ = self;
            return dtype.canCast(target);
        }

        pub fn can_cast_to_dtype(self: Self, target: DType) bool {
            return self.canCastToDtype(target);
        }

        pub fn fromArray(input: Array(T)) ArrayError!Self {
            const shape = try input.allocator.dupe(usize, input.shape);
            errdefer input.allocator.free(shape);
            const strides = try input.allocator.dupe(usize, input.strides);
            return .{
                .allocator = input.allocator,
                .data = input.data,
                .shape = shape,
                .strides = strides,
                .offset = 0,
                .device = input.device,
            };
        }

        pub fn init(
            allocator: std.mem.Allocator,
            data: []T,
            dims: []const usize,
            stride_values: []const usize,
            offset: usize,
            device: Device,
        ) ArrayError!Self {
            if (dims.len != stride_values.len) return error.InvalidShape;
            const shape = try allocator.dupe(usize, dims);
            errdefer allocator.free(shape);
            const strides = try allocator.dupe(usize, stride_values);
            return .{
                .allocator = allocator,
                .data = data,
                .shape = shape,
                .strides = strides,
                .offset = offset,
                .device = device,
            };
        }

        pub fn deinit(self: *Self) void {
            self.allocator.free(self.shape);
            self.allocator.free(self.strides);
            self.* = undefined;
        }

        pub fn clone(self: Self) ArrayError!Self {
            return Self.init(self.allocator, self.data, self.shape, self.strides, self.offset, self.device);
        }

        pub fn copy(self: Self) ArrayError!Array(T) {
            return self.toArray();
        }

        pub fn detach(self: Self) ArrayError!Array(T) {
            return self.copy();
        }

        pub fn ndim(self: Self) usize {
            return self.shape.len;
        }

        pub fn dim(self: Self) usize {
            return self.ndim();
        }

        pub fn rank(self: Self) usize {
            return self.ndim();
        }

        pub fn numDims(self: Self) usize {
            return self.ndim();
        }

        pub fn num_dims(self: Self) usize {
            return self.numDims();
        }

        pub fn numel(self: Self) usize {
            return product(self.shape);
        }

        pub fn nelement(self: Self) usize {
            return self.numel();
        }

        pub fn isEmpty(self: Self) bool {
            return self.numel() == 0;
        }

        pub fn is_empty(self: Self) bool {
            return self.isEmpty();
        }

        pub fn isMatrix(self: Self) bool {
            return self.shape.len == 2;
        }

        pub fn is_matrix(self: Self) bool {
            return self.isMatrix();
        }

        pub fn isBatchedMatrix(self: Self) bool {
            return self.shape.len >= 3;
        }

        pub fn is_batched_matrix(self: Self) bool {
            return self.isBatchedMatrix();
        }

        pub fn isSquare(self: Self) bool {
            return self.shape.len >= 2 and self.shape[self.shape.len - 2] == self.shape[self.shape.len - 1];
        }

        pub fn is_square(self: Self) bool {
            return self.isSquare();
        }

        pub fn size(self: Self, axis_opt: ?isize) ArrayError!usize {
            if (axis_opt) |axis_index| return self.shape[try normalizeDim(axis_index, self.shape.len)];
            return self.numel();
        }

        pub fn shapeAt(self: Self, axis_index: isize) ArrayError!usize {
            return self.shape[try normalizeDim(axis_index, self.shape.len)];
        }

        pub fn shape_at(self: Self, axis_index: isize) ArrayError!usize {
            return self.shapeAt(axis_index);
        }

        pub fn len(self: Self) ArrayError!usize {
            if (self.shape.len == 0) return error.InvalidShape;
            return self.shape[0];
        }

        pub fn stride(self: Self, axis_index: isize) ArrayError!usize {
            return self.strides[try normalizeDim(axis_index, self.shape.len)];
        }

        pub fn strideAt(self: Self, axis_index: isize) ArrayError!usize {
            return self.stride(axis_index);
        }

        pub fn stride_at(self: Self, axis_index: isize) ArrayError!usize {
            return self.strideAt(axis_index);
        }

        pub fn elementSize(self: Self) usize {
            _ = self;
            return @sizeOf(T);
        }

        pub fn element_size(self: Self) usize {
            return self.elementSize();
        }

        pub fn itemsize(self: Self) usize {
            return self.elementSize();
        }

        pub fn nbytes(self: Self) usize {
            return self.numel() * @sizeOf(T);
        }

        pub fn num_bytes(self: Self) usize {
            return self.nbytes();
        }

        pub fn storageOffset(self: Self) usize {
            return self.offset;
        }

        pub fn storage_offset(self: Self) usize {
            return self.storageOffset();
        }

        pub fn dataPtr(self: Self) [*]T {
            return self.data.ptr + self.offset;
        }

        pub fn data_ptr(self: Self) [*]T {
            return self.dataPtr();
        }

        pub fn storageDataPtr(self: Self) [*]T {
            return self.data.ptr;
        }

        pub fn storage_data_ptr(self: Self) [*]T {
            return self.storageDataPtr();
        }

        pub fn storageSize(self: Self) usize {
            return self.data.len;
        }

        pub fn storage_size(self: Self) usize {
            return self.storageSize();
        }

        pub fn storageNbytes(self: Self) usize {
            return self.data.len * @sizeOf(T);
        }

        pub fn storage_nbytes(self: Self) usize {
            return self.storageNbytes();
        }

        pub fn storageSpan(self: Self) ArrayError!usize {
            return computeStorageSpan(self.shape, self.strides);
        }

        pub fn storage_span(self: Self) ArrayError!usize {
            return self.storageSpan();
        }

        pub fn storageRange(self: Self) ArrayError!StorageRange {
            return computeStorageRange(self.offset, self.shape, self.strides);
        }

        pub fn storage_range(self: Self) ArrayError!StorageRange {
            return self.storageRange();
        }

        pub fn storageEndOffset(self: Self) ArrayError!usize {
            return (try self.storageRange()).end;
        }

        pub fn storage_end_offset(self: Self) ArrayError!usize {
            return self.storageEndOffset();
        }

        pub fn sharesStorage(self: Self, other: Self) bool {
            return self.data.ptr == other.data.ptr and self.data.len == other.data.len;
        }

        pub fn shares_storage(self: Self, other: Self) bool {
            return self.sharesStorage(other);
        }

        pub fn sameStorage(self: Self, other: Self) bool {
            return self.sharesStorage(other);
        }

        pub fn same_storage(self: Self, other: Self) bool {
            return self.sameStorage(other);
        }

