        pub fn astype(self: Self, comptime U: type) ArrayError!Array(U) {
            var out = try Array(U).empty(self.allocator, self.shape);
            errdefer out.deinit();
            if (out.data.len == 0) return out;
            const multi = try self.allocator.alloc(usize, self.shape.len);
