                    if (comptime T == BFloat16) {
                        const value = a.toF32();
                        const softplus_value = @max(value, @as(f32, 0)) + std.math.log1p(std.math.exp(-@abs(value)));
                        return BFloat16.fromF32(value * std.math.tanh(softplus_value));
                    }
                    const softplus_value = @max(a, zero(T)) + std.math.log1p(std.math.exp(-@abs(a)));
                    return a * std.math.tanh(softplus_value);
                }
            }.f);
        }

        pub fn hardsigmoid(self: Self) ArrayError!Array(T) {
            ensureFloat(T);
            return self.unary(struct {
                fn f(a: T) T {
                    if (comptime T == BFloat16) {
                        const value = a.toF32();
                        return BFloat16.fromF32(@min(@max((value + @as(f32, 3)) / @as(f32, 6), @as(f32, 0)), @as(f32, 1)));
                    }
                    return @min(@max((a + castValue(T, 3)) / castValue(T, 6), zero(T)), one(T));
                }
            }.f);
        }

        pub fn hardSigmoid(self: Self) ArrayError!Array(T) {
            return self.hardsigmoid();
        }

        pub fn hardswish(self: Self) ArrayError!Array(T) {
            ensureFloat(T);
            return self.unary(struct {
                fn f(a: T) T {
                    if (comptime T == BFloat16) {
                        const value = a.toF32();
                        const gate = @min(@max((value + @as(f32, 3)) / @as(f32, 6), @as(f32, 0)), @as(f32, 1));
                        return BFloat16.fromF32(value * gate);
                    }
                    const gate = @min(@max((a + castValue(T, 3)) / castValue(T, 6), zero(T)), one(T));
                    return a * gate;
                }
            }.f);
        }

        pub fn hardSwish(self: Self) ArrayError!Array(T) {
            return self.hardswish();
        }

        pub fn logsigmoid(self: Self) ArrayError!Array(T) {
            ensureFloat(T);
            return self.unary(struct {
                fn f(a: T) T {
                    if (comptime T == BFloat16) {
                        const value = a.toF32();
                        const softplus_neg = @max(-value, @as(f32, 0)) + std.math.log1p(std.math.exp(-@abs(value)));
                        return BFloat16.fromF32(-softplus_neg);
                    }
                    const softplus_neg = @max(negValue(T, a), zero(T)) + std.math.log1p(std.math.exp(-@abs(a)));
                    return negValue(T, softplus_neg);
                }
            }.f);
        }

        pub fn logSigmoid(self: Self) ArrayError!Array(T) {
            return self.logsigmoid();
        }

        pub fn log_sigmoid(self: Self) ArrayError!Array(T) {
