        pub fn sliceAxis(self: Self, axis_index: isize, slice_value: Slice) ArrayError!Self {
            if (self.shape.len == 0) return error.InvalidAxis;
            const axis = try normalizeDim(axis_index, self.shape.len);
            const ns = try normalizeSlice(slice_value, self.shape[axis]);
            const shape = try self.allocator.dupe(usize, self.shape);
            errdefer self.allocator.free(shape);
            const strides = try self.allocator.dupe(usize, self.strides);
            shape[axis] = ns.count;
            strides[axis] *= ns.step;
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = shape,
                .strides = strides,
                .offset = self.offset + ns.start * self.strides[axis],
                .device = self.device,
            };
        }

        pub fn slice(self: Self, slices: []const Slice) ArrayError!Self {
            if (slices.len != self.shape.len) return error.ShapeMismatch;
            var current = try self.clone();
            errdefer current.deinit();
            for (slices, 0..) |slice_value, axis| {
                const next = try current.sliceAxis(@intCast(axis), slice_value);
                current.deinit();
                current = next;
            }
            return current;
        }

        pub fn narrow(self: Self, axis_index: isize, start: usize, length: usize) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (start > self.shape[axis] or start + length > self.shape[axis]) return error.IndexOutOfBounds;
            return self.sliceAxis(axis_index, .{ .start = @intCast(start), .stop = @intCast(start + length), .step = 1 });
        }

        pub fn narrowSigned(self: Self, axis_index: isize, start: isize, length: usize) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            const normalized_start = try normalizeIndex(start, self.shape[axis]);
            return self.narrow(axis_index, normalized_start, length);
        }

        pub fn narrow_signed(self: Self, axis_index: isize, start: isize, length: usize) ArrayError!Self {
            return self.narrowSigned(axis_index, start, length);
        }

        pub fn select(self: Self, axis_index: isize, index: usize) ArrayError!Self {
            if (self.shape.len == 0) return error.InvalidAxis;
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (index >= self.shape[axis]) return error.IndexOutOfBounds;
            const shape = try self.allocator.alloc(usize, self.shape.len - 1);
            errdefer self.allocator.free(shape);
            const strides = try self.allocator.alloc(usize, self.strides.len - 1);
            for (self.shape[0..axis], 0..) |extent, i| shape[i] = extent;
            for (self.shape[axis + 1 ..], axis..) |extent, i| shape[i] = extent;
            for (self.strides[0..axis], 0..) |stride_value, i| strides[i] = stride_value;
            for (self.strides[axis + 1 ..], axis..) |stride_value, i| strides[i] = stride_value;
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = shape,
                .strides = strides,
                .offset = self.offset + index * self.strides[axis],
                .device = self.device,
            };
        }

        pub fn selectSigned(self: Self, axis_index: isize, index: isize) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            return self.select(axis_index, try normalizeIndex(index, self.shape[axis]));
        }

        pub fn select_signed(self: Self, axis_index: isize, index: isize) ArrayError!Self {
            return self.selectSigned(axis_index, index);
        }

        pub fn squeeze(self: Self, axis_opt: ?isize) ArrayError!Self {
            var shape_list: std.ArrayList(usize) = .empty;
            defer shape_list.deinit(self.allocator);
            var stride_list: std.ArrayList(usize) = .empty;
            defer stride_list.deinit(self.allocator);
            if (axis_opt) |axis_index| {
                const axis = try normalizeDim(axis_index, self.shape.len);
                for (self.shape, self.strides, 0..) |extent, stride_value, i| {
                    if (i == axis and extent == 1) continue;
                    try shape_list.append(self.allocator, extent);
                    try stride_list.append(self.allocator, stride_value);
                }
            } else {
                for (self.shape, self.strides) |extent, stride_value| {
                    if (extent == 1) continue;
                    try shape_list.append(self.allocator, extent);
                    try stride_list.append(self.allocator, stride_value);
                }
            }
            return Self.init(self.allocator, self.data, shape_list.items, stride_list.items, self.offset, self.device);
        }

        pub fn squeezeDim(self: Self, axis_index: isize) ArrayError!Self {
            return self.squeeze(axis_index);
        }

        pub fn squeeze_dim(self: Self, axis_index: isize) ArrayError!Self {
            return self.squeezeDim(axis_index);
        }

        pub fn squeezeView(self: Self, axis_opt: ?isize) ArrayError!Self {
            return self.squeeze(axis_opt);
        }

        pub fn squeeze_view(self: Self, axis_opt: ?isize) ArrayError!Self {
            return self.squeezeView(axis_opt);
        }

        pub fn squeezeDimView(self: Self, axis_index: isize) ArrayError!Self {
            return self.squeezeDim(axis_index);
        }

        pub fn squeeze_dim_view(self: Self, axis_index: isize) ArrayError!Self {
            return self.squeezeDimView(axis_index);
        }

        pub fn squeezeAxes(self: Self, axes: []const isize) ArrayError!Self {
            if (axes.len == 0) return self.clone();
            const normalized_axes = try normalizeUniqueAxes(self.allocator, axes, self.shape.len);
            defer self.allocator.free(normalized_axes);
            var squeeze_mask = try self.allocator.alloc(bool, self.shape.len);
            defer self.allocator.free(squeeze_mask);
            @memset(squeeze_mask, false);
            for (normalized_axes) |axis| {
                if (self.shape[axis] != 1) return error.ShapeMismatch;
                squeeze_mask[axis] = true;
            }
            var shape_list: std.ArrayList(usize) = .empty;
            defer shape_list.deinit(self.allocator);
            var stride_list: std.ArrayList(usize) = .empty;
            defer stride_list.deinit(self.allocator);
            for (self.shape, self.strides, 0..) |extent, stride_value, axis| {
                if (squeeze_mask[axis]) continue;
                try shape_list.append(self.allocator, extent);
                try stride_list.append(self.allocator, stride_value);
            }
            return Self.init(self.allocator, self.data, shape_list.items, stride_list.items, self.offset, self.device);
        }

        pub fn squeeze_axes(self: Self, axes: []const isize) ArrayError!Self {
            return self.squeezeAxes(axes);
        }

        pub fn squeezeAxesView(self: Self, axes: []const isize) ArrayError!Self {
            return self.squeezeAxes(axes);
        }

        pub fn squeeze_axes_view(self: Self, axes: []const isize) ArrayError!Self {
            return self.squeezeAxesView(axes);
        }

        pub fn unsqueeze(self: Self, axis_index: isize) ArrayError!Self {
            const rank_count = self.shape.len + 1;
            const axis = if (axis_index < 0) blk: {
                const signed_rank: isize = @intCast(rank_count);
                const normalized = signed_rank + axis_index;
                if (normalized < 0 or normalized >= signed_rank) return error.InvalidAxis;
                break :blk @as(usize, @intCast(normalized));
            } else try canonicalAxis(@intCast(axis_index), rank_count);
            const shape = try self.allocator.alloc(usize, rank_count);
            errdefer self.allocator.free(shape);
            const strides = try self.allocator.alloc(usize, rank_count);
            for (self.shape[0..axis], 0..) |extent, i| shape[i] = extent;
            shape[axis] = 1;
            for (self.shape[axis..], axis + 1..) |extent, i| shape[i] = extent;
            for (self.strides[0..axis], 0..) |stride_value, i| strides[i] = stride_value;
            strides[axis] = 0;
            for (self.strides[axis..], axis + 1..) |stride_value, i| strides[i] = stride_value;
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = shape,
                .strides = strides,
                .offset = self.offset,
                .device = self.device,
            };
        }

        pub fn unsqueezeDim(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueeze(axis_index);
        }

        pub fn unsqueeze_dim(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueezeDim(axis_index);
        }

        pub fn unsqueezeView(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueeze(axis_index);
        }

        pub fn unsqueeze_view(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueezeView(axis_index);
        }

        pub fn unsqueezeDimView(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueezeDim(axis_index);
        }

        pub fn unsqueeze_dim_view(self: Self, axis_index: isize) ArrayError!Self {
            return self.unsqueezeDimView(axis_index);
        }

        pub fn unsqueezeAxes(self: Self, axes: []const isize) ArrayError!Self {
            if (axes.len == 0) return self.clone();
            const out_rank = self.shape.len + axes.len;
            const normalized_axes = try normalizeInsertAxesAscending(self.allocator, axes, out_rank);
            defer self.allocator.free(normalized_axes);
            const shape = try self.allocator.alloc(usize, out_rank);
            errdefer self.allocator.free(shape);
            const strides = try self.allocator.alloc(usize, out_rank);
            errdefer self.allocator.free(strides);
            var read_axis: usize = 0;
            var insert_index: usize = 0;
            for (0..out_rank) |axis| {
                if (insert_index < normalized_axes.len and normalized_axes[insert_index] == axis) {
                    shape[axis] = 1;
                    strides[axis] = 0;
                    insert_index += 1;
                } else {
                    shape[axis] = self.shape[read_axis];
                    strides[axis] = self.strides[read_axis];
                    read_axis += 1;
                }
            }
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = shape,
                .strides = strides,
                .offset = self.offset,
                .device = self.device,
            };
        }

        pub fn unsqueeze_axes(self: Self, axes: []const isize) ArrayError!Self {
            return self.unsqueezeAxes(axes);
        }

        pub fn unsqueezeAxesView(self: Self, axes: []const isize) ArrayError!Self {
            return self.unsqueezeAxes(axes);
        }

        pub fn unsqueeze_axes_view(self: Self, axes: []const isize) ArrayError!Self {
            return self.unsqueezeAxesView(axes);
        }

        pub fn expandDims(self: Self, axes: []const isize) ArrayError!Self {
            return self.unsqueezeAxes(axes);
        }

        pub fn expand_dims(self: Self, axes: []const isize) ArrayError!Self {
            return self.expandDims(axes);
        }

        pub fn expandDimsView(self: Self, axes: []const isize) ArrayError!Self {
            return self.expandDims(axes);
        }

        pub fn expand_dims_view(self: Self, axes: []const isize) ArrayError!Self {
            return self.expandDimsView(axes);
        }

        pub fn broadcastTo(self: Self, dims: []const usize) ArrayError!Self {
            const out_shape = try computeBroadcastShape(self.allocator, self.shape, dims);
            errdefer self.allocator.free(out_shape);
            if (!std.mem.eql(usize, out_shape, dims)) return error.ShapeMismatch;
            const out_strides = try self.allocator.alloc(usize, dims.len);
            const leading = dims.len - self.shape.len;
            for (out_strides, 0..) |*slot, axis| {
                if (axis < leading) {
                    slot.* = 0;
                } else {
                    const in_axis = axis - leading;
                    slot.* = if (self.shape[in_axis] == 1 and dims[axis] != 1) 0 else self.strides[in_axis];
                }
            }
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = out_shape,
                .strides = out_strides,
                .offset = self.offset,
                .device = self.device,
            };
        }

        pub fn broadcast_to(self: Self, dims: []const usize) ArrayError!Self {
            return self.broadcastTo(dims);
        }

        pub fn broadcastToView(self: Self, dims: []const usize) ArrayError!Self {
            return self.broadcastTo(dims);
        }

        pub fn broadcast_to_view(self: Self, dims: []const usize) ArrayError!Self {
            return self.broadcastToView(dims);
        }

        pub fn expand(self: Self, dims: []const usize) ArrayError!Self {
            return self.broadcastTo(dims);
        }

        pub fn expandToView(self: Self, dims: []const usize) ArrayError!Self {
            return self.expand(dims);
        }

        pub fn expand_to_view(self: Self, dims: []const usize) ArrayError!Self {
            return self.expandToView(dims);
        }

        pub fn expandAs(self: Self, other: Self) ArrayError!Self {
            return self.expand(other.shape);
        }

        pub fn expandAsArray(self: Self, other: Array(T)) ArrayError!Self {
            return self.expand(other.shape);
        }

        pub fn expand_as_array(self: Self, other: Array(T)) ArrayError!Self {
            return self.expandAsArray(other);
        }

        pub fn expandAsView(self: Self, other: Self) ArrayError!Self {
            return self.expand(other.shape);
        }

        pub fn expand_as_view(self: Self, other: Self) ArrayError!Self {
            return self.expandAsView(other);
        }

        pub fn broadcastAs(self: Self, other: Self) ArrayError!Self {
            return self.expandAs(other);
        }

        pub fn broadcast_as(self: Self, other: Self) ArrayError!Self {
            return self.broadcastAs(other);
        }

        pub fn broadcastAsArray(self: Self, other: Array(T)) ArrayError!Self {
            return self.expandAsArray(other);
        }

        pub fn broadcast_as_array(self: Self, other: Array(T)) ArrayError!Self {
            return self.broadcastAsArray(other);
        }

        pub fn broadcastAsView(self: Self, other: Self) ArrayError!Self {
            return self.expandAsView(other);
        }

        pub fn broadcast_as_view(self: Self, other: Self) ArrayError!Self {
            return self.broadcastAsView(other);
        }

        pub fn expand_as(self: Self, other: Self) ArrayError!Self {
            return self.expandAs(other);
        }

        pub fn permute(self: Self, axes: []const usize) ArrayError!Self {
            if (axes.len != self.shape.len) return error.InvalidPermutation;
            var seen = try self.allocator.alloc(bool, axes.len);
            defer self.allocator.free(seen);
            @memset(seen, false);
            const shape = try self.allocator.alloc(usize, axes.len);
            errdefer self.allocator.free(shape);
            const strides = try self.allocator.alloc(usize, axes.len);
            errdefer self.allocator.free(strides);
            for (axes, 0..) |axis, i| {
                if (axis >= axes.len or seen[axis]) return error.InvalidPermutation;
                seen[axis] = true;
                shape[i] = self.shape[axis];
                strides[i] = self.strides[axis];
            }
            return .{
                .allocator = self.allocator,
                .data = self.data,
                .shape = shape,
                .strides = strides,
                .offset = self.offset,
                .device = self.device,
            };
        }

        pub fn permuteView(self: Self, axes: []const usize) ArrayError!Self {
            return self.permute(axes);
        }

        pub fn permute_view(self: Self, axes: []const usize) ArrayError!Self {
            return self.permuteView(axes);
        }

        pub fn swapaxes(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            const a0 = try normalizeDim(dim0, self.shape.len);
            const a1 = try normalizeDim(dim1, self.shape.len);
            var axes = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(axes);
            for (axes, 0..) |*slot, i| slot.* = i;
            std.mem.swap(usize, &axes[a0], &axes[a1]);
            return self.permute(axes);
        }

        pub fn swapaxesView(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapaxes(dim0, dim1);
        }

        pub fn swapaxes_view(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapaxesView(dim0, dim1);
        }

        pub fn swapDims(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapaxes(dim0, dim1);
        }

        pub fn swap_dims(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapDims(dim0, dim1);
        }

        pub fn swapDimsView(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapDims(dim0, dim1);
        }

        pub fn swap_dims_view(self: Self, dim0: isize, dim1: isize) ArrayError!Self {
            return self.swapDimsView(dim0, dim1);
        }

        pub fn movedim(self: Self, source: isize, destination: isize) ArrayError!Self {
            const src = try normalizeDim(source, self.shape.len);
            const dst = try normalizeDim(destination, self.shape.len);
            const axes = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(axes);
            var remaining = try self.allocator.alloc(usize, self.shape.len - 1);
            defer self.allocator.free(remaining);
            var remaining_len: usize = 0;
            for (0..self.shape.len) |i| {
                if (i == src) continue;
                remaining[remaining_len] = i;
                remaining_len += 1;
            }
            var read: usize = 0;
            for (axes, 0..) |*slot, out_i| {
                if (out_i == dst) {
                    slot.* = src;
                } else {
                    slot.* = remaining[read];
                    read += 1;
                }
            }
            return self.permute(axes);
        }

        pub fn movedimView(self: Self, source: isize, destination: isize) ArrayError!Self {
            return self.movedim(source, destination);
        }

        pub fn movedim_view(self: Self, source: isize, destination: isize) ArrayError!Self {
            return self.movedimView(source, destination);
        }

        pub fn moveaxis(self: Self, source: isize, destination: isize) ArrayError!Self {
            return self.movedim(source, destination);
        }

        pub fn moveaxisView(self: Self, source: isize, destination: isize) ArrayError!Self {
            return self.moveaxis(source, destination);
        }

        pub fn moveaxis_view(self: Self, source: isize, destination: isize) ArrayError!Self {
            return self.moveaxisView(source, destination);
        }

        pub fn moveaxes(self: Self, sources: []const isize, destinations: []const isize) ArrayError!Self {
            const axes = try movedimManyAxes(self.allocator, self.shape.len, sources, destinations);
            defer self.allocator.free(axes);
            return self.permute(axes);
        }

        pub fn move_axes(self: Self, sources: []const isize, destinations: []const isize) ArrayError!Self {
            return self.moveaxes(sources, destinations);
        }

        pub fn moveaxesView(self: Self, sources: []const isize, destinations: []const isize) ArrayError!Self {
            return self.moveaxes(sources, destinations);
        }

        pub fn moveaxes_view(self: Self, sources: []const isize, destinations: []const isize) ArrayError!Self {
            return self.moveaxesView(sources, destinations);
        }

        pub fn move_axes_view(self: Self, sources: []const isize, destinations: []const isize) ArrayError!Self {
            return self.moveaxesView(sources, destinations);
        }

        pub fn transpose(self: Self) ArrayError!Self {
            if (self.shape.len != 2) return error.NonMatrixArray;
            return self.swapaxes(0, 1);
        }

        pub fn T_(self: Self) ArrayError!Self {
            return self.transpose();
        }

        pub fn transposeView(self: Self) ArrayError!Self {
            return self.transpose();
        }

        pub fn transpose_view(self: Self) ArrayError!Self {
            return self.transposeView();
        }

        pub fn TView(self: Self) ArrayError!Self {
            return self.transposeView();
        }

        pub fn T_view(self: Self) ArrayError!Self {
            return self.TView();
        }

        pub fn matrixTranspose(self: Self) ArrayError!Self {
            if (self.shape.len < 2) return error.NonMatrixArray;
            return self.swapaxes(@as(isize, @intCast(self.shape.len - 2)), @as(isize, @intCast(self.shape.len - 1)));
        }

        pub fn matrix_transpose(self: Self) ArrayError!Self {
            return self.matrixTranspose();
        }

        pub fn mT(self: Self) ArrayError!Self {
            return self.matrixTranspose();
        }

        pub fn matrixTransposeView(self: Self) ArrayError!Self {
            return self.matrixTranspose();
        }

        pub fn matrix_transpose_view(self: Self) ArrayError!Self {
            return self.matrixTransposeView();
        }

        pub fn mTView(self: Self) ArrayError!Self {
            return self.matrixTransposeView();
        }

        pub fn mT_view(self: Self) ArrayError!Self {
            return self.mTView();
        }

        pub fn adjoint(self: Self) ArrayError!Array(T) {
            var transposed_view = try self.matrixTranspose();
            defer transposed_view.deinit();
            if (comptime isComplex(T)) return transposed_view.conj();
            return transposed_view.toArray();
        }

        pub fn mH(self: Self) ArrayError!Array(T) {
            return self.adjoint();
        }

        pub fn H_(self: Self) ArrayError!Array(T) {
            return self.adjoint();
        }

        pub fn matrixPower(self: Self, exponent: isize) ArrayError!Array(T) {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.matrixPower(exponent);
        }

        pub fn matrix_power(self: Self, exponent: isize) ArrayError!Array(T) {
            return self.matrixPower(exponent);
        }

        pub fn isDiagonalMatrix(self: Self) ArrayError!bool {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.isDiagonalMatrix();
        }

        pub fn is_diagonal_matrix(self: Self) ArrayError!bool {
            return self.isDiagonalMatrix();
        }

        pub fn isUpperTriangular(self: Self) ArrayError!bool {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.isUpperTriangular();
        }

        pub fn is_upper_triangular(self: Self) ArrayError!bool {
            return self.isUpperTriangular();
        }

        pub fn isLowerTriangular(self: Self) ArrayError!bool {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.isLowerTriangular();
        }

        pub fn is_lower_triangular(self: Self) ArrayError!bool {
            return self.isLowerTriangular();
        }

        pub fn isSymmetric(self: Self, rtol: T, atol: T) ArrayError!bool {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.isSymmetric(rtol, atol);
        }

        pub fn is_symmetric(self: Self, rtol: T, atol: T) ArrayError!bool {
            return self.isSymmetric(rtol, atol);
        }

        pub fn isHermitian(self: Self, rtol: T, atol: T) ArrayError!bool {
            var owned = try self.toArray();
            defer owned.deinit();
            return owned.isHermitian(rtol, atol);
        }

        pub fn is_hermitian(self: Self, rtol: T, atol: T) ArrayError!bool {
            return self.isHermitian(rtol, atol);
        }
    };
}

pub fn Array(comptime T: type) type {
    return struct {
        const Self = @This();

        allocator: std.mem.Allocator,
        data: []T,
        shape: []usize,
        strides: []usize,
        device: Device = .cpu,
        device_storage: ?DeviceStorage = null,
        pending_matmul: ?MatmulFusion = null,
        cpu_matmul: ?CpuMatmulFusion = null,

        const MatmulFusion = struct {
            lhs_storage: DeviceStorage,
            rhs_storage: DeviceStorage,
            add_storage: ?DeviceStorage = null,
            lhs_shape: [2]usize,
            rhs_shape: [2]usize,
            alpha: f32 = 1.0,
            beta: f32 = 0.0,
            unary: ?PendingUnary = null,
        };

        const PendingUnary = enum {
            sqrt,
            exp,
        };

        pub const FusionKind = enum {
            none,
            cuda_matmul,
            cuda_matmul_add,
            cuda_matmul_sub,
            cuda_matmul_rsub,
            cuda_matmul_add_sqrt,
            cuda_matmul_add_exp,
            cuda_matmul_sub_sqrt,
            cuda_matmul_sub_exp,
            cuda_matmul_rsub_sqrt,
            cuda_matmul_rsub_exp,
            cpu_matmul,
            cpu_matmul_add,
            cpu_matmul_sub,
            cpu_matmul_rsub,
            cpu_matmul_add_sqrt,
            cpu_matmul_add_exp,
            cpu_matmul_sub_sqrt,
            cpu_matmul_sub_exp,
            cpu_matmul_rsub_sqrt,
            cpu_matmul_rsub_exp,
        };

        const CpuMatmulFusion = struct {
            lhs_data: []T,
            rhs_data: []T,
            lhs_shape: [2]usize,
            rhs_shape: [2]usize,
            alpha: f32 = 1.0,
            beta: f32 = 0.0,
            unary: ?PendingUnary = null,
        };

        pub const Scalar = T;
        pub const dtype = DType.of(T);
        pub const BroadcastPair = ArrayView(T).BroadcastPair;

        pub fn dtypeName(self: Self) []const u8 {
            _ = self;
            return dtype.name();
        }

        pub fn fusionStatus(self: Self) FusionKind {
            if (self.pending_matmul) |pending| {
                if (pending.add_storage == null) return .cuda_matmul;
                const is_rsub = pending.alpha < 0.0;
                const is_sub = pending.beta < 0.0;
                if (pending.unary) |unary_op| {
                    return switch (unary_op) {
                        .sqrt => if (is_rsub) .cuda_matmul_rsub_sqrt else if (is_sub) .cuda_matmul_sub_sqrt else .cuda_matmul_add_sqrt,
                        .exp => if (is_rsub) .cuda_matmul_rsub_exp else if (is_sub) .cuda_matmul_sub_exp else .cuda_matmul_add_exp,
                    };
                }
                if (is_rsub) return .cuda_matmul_rsub;
                return if (is_sub) .cuda_matmul_sub else .cuda_matmul_add;
            }
            if (self.cpu_matmul) |cpu_fusion| {
                if (cpu_fusion.beta == 0.0) return .cpu_matmul;
                const is_rsub = cpu_fusion.alpha < 0.0;
                const is_sub = cpu_fusion.beta < 0.0;
                if (cpu_fusion.unary) |unary_op| {
                    return switch (unary_op) {
                        .sqrt => if (is_rsub) .cpu_matmul_rsub_sqrt else if (is_sub) .cpu_matmul_sub_sqrt else .cpu_matmul_add_sqrt,
                        .exp => if (is_rsub) .cpu_matmul_rsub_exp else if (is_sub) .cpu_matmul_sub_exp else .cpu_matmul_add_exp,
                    };
                }
                if (is_rsub) return .cpu_matmul_rsub;
                return if (is_sub) .cpu_matmul_sub else .cpu_matmul_add;
            }
            return .none;
        }

        pub fn fusion_status(self: Self) FusionKind {
