            var out = try Self.empty(allocator, &.{ samples, alpha.len });
            errdefer out.deinit();
            var engine = alea.ScalarPrng.init(seed);
            const rng = alea.Rng.init(&engine);
            distribution.sampleManyIntoChecked(rng, out.data) catch return error.InvalidShape;
            return out;
        }

