        pub fn chiSquared(allocator: std.mem.Allocator, dims: []const usize, dof: T, seed: u64) ArrayError!Self {
            return randomFromAlea(allocator, dims, seed, dof, struct {
                fn f(rng: alea.Rng, value: T) ArrayError!T {
