        pub fn deinit(self: *Self) void {
            if (self.device_storage) |storage| axiom_cuda_backend.freeStorage(storage);
            self.pending_matmul = null;
            self.cpu_matmul = null;
            self.allocator.free(self.data);
            self.allocator.free(self.shape);
            self.allocator.free(self.strides);
            self.* = undefined;
        }

        pub fn clone(self: Self) ArrayError!Self {
            if (self.pending_matmul != null) return self.materializePendingMatmul();
            var out = try Self.emptyOn(self.allocator, self.shape, self.device);
            errdefer out.deinit();
            if (self.device.isCpu()) {
                @memcpy(out.data, self.data);
            } else if (self.device_storage) |src_storage| {
                if (out.device_storage) |dst_storage| try axiom_cuda_backend.copyStorage(dst_storage, src_storage) else return error.InvalidDevice;
            } else {
                return error.InvalidDevice;
            }
            return out;
        }

        pub fn copy(self: Self) ArrayError!Self {
            return self.clone();
        }

        pub fn detach(self: Self) ArrayError!Self {
            return self.copy();
        }

        pub fn materialize(self: Self) ArrayError!Self {
            if (self.pending_matmul != null) return self.materializePendingMatmul();
            return self.clone();
        }

        pub fn astype(self: Self, comptime U: type) ArrayError!Array(U) {
            if (!self.device.isCpu()) {
                var host = try self.to(.cpu);
                defer host.deinit();
                var out = try host.astype(U);
                if (self.device.isCuda()) {
                    const device_out = try out.to(self.device);
                    out.deinit();
                    return device_out;
                }
                return out;
            }
            const out = try Array(U).empty(self.allocator, self.shape);
            for (self.data, out.data) |v, *slot| {
                slot.* = castValue(U, v);
            }
            return out;
        }

        fn toVeyraMatrixF64(self: Self) ArrayError!veyra.Matrix(f64) {
            if (comptime T != f64) @compileError("Veyra dense backend path requires Array(f64)");
            if (self.shape.len != 2) return error.NonMatrixArray;
            return veyra.Matrix(f64).fromSlice(self.allocator, self.shape[0], self.shape[1], .row_major, self.data) catch |err| return mapVeyraArrayError(err);
        }

        fn toVeyraVectorF64(self: Self) ArrayError!veyra.Vector(f64) {
            if (comptime T != f64) @compileError("Veyra dense backend path requires Array(f64)");
            if (self.shape.len != 1) return error.NonVectorArray;
            return veyra.Vector(f64).fromSlice(self.allocator, self.data) catch |err| return mapVeyraArrayError(err);
        }

        fn fromVeyraMatrixF64(allocator: std.mem.Allocator, matrix: *const veyra.Matrix(f64)) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense backend path requires Array(f64)");
            return Self.fromSlice(allocator, matrix.data, &.{ matrix.rows, matrix.cols });
        }

        fn fromVeyraVectorF64(allocator: std.mem.Allocator, vector: *const veyra.Vector(f64)) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense backend path requires Array(f64)");
            return Self.fromSlice(allocator, vector.data, &.{vector.len()});
        }

        fn matmul2dContiguousF64(self: Self, other: Self) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense matmul fast path requires Array(f64)");
            if (self.shape.len != 2 or other.shape.len != 2) return error.NonMatrixArray;
            if (self.shape[1] != other.shape[0]) return error.ShapeMismatch;
            if (!self.isContiguous() or !other.isContiguous()) return error.InvalidShape;

            var out = try Self.empty(self.allocator, &.{ self.shape[0], other.shape[1] });
            errdefer out.deinit();
            if (out.data.len == 0) return out;
            if (self.shape[1] == 0) {
                @memset(out.data, 0);
                return out;
            }

            const lhs = veyra.MatrixView(f64).fromStridedSlice(
                self.data,
                self.shape[0],
                self.shape[1],
                try usizeToPositiveIsize(self.strides[0]),
                try usizeToPositiveIsize(self.strides[1]),
            ) catch |err| return mapVeyraArrayError(err);
            const rhs = veyra.MatrixView(f64).fromStridedSlice(
                other.data,
                other.shape[0],
                other.shape[1],
                try usizeToPositiveIsize(other.strides[0]),
                try usizeToPositiveIsize(other.strides[1]),
            ) catch |err| return mapVeyraArrayError(err);
            const dst = veyra.MatrixMut(f64).fromSlice(
                out.data,
                out.shape[0],
                out.shape[1],
                .row_major,
            ) catch |err| return mapVeyraArrayError(err);
            veyra.matmul(f64, lhs, rhs, dst) catch |err| return mapVeyraArrayError(err);
            return out;
        }

        fn veyraVectorViewF64(self: Self) ArrayError!veyra.VectorView(f64) {
            if (comptime T != f64) @compileError("Veyra dense vector fast path requires Array(f64)");
            if (self.shape.len != 1) return error.NonVectorArray;
            return veyra.VectorView(f64).fromStridedSlice(
                self.data,
                self.shape[0],
                try usizeToPositiveIsize(self.strides[0]),
            ) catch |err| return mapVeyraArrayError(err);
        }

        fn veyraMatrixViewF64(self: Self) ArrayError!veyra.MatrixView(f64) {
            if (comptime T != f64) @compileError("Veyra dense matrix fast path requires Array(f64)");
            if (self.shape.len != 2) return error.NonMatrixArray;
            return veyra.MatrixView(f64).fromStridedSlice(
                self.data,
                self.shape[0],
                self.shape[1],
                try usizeToPositiveIsize(self.strides[0]),
                try usizeToPositiveIsize(self.strides[1]),
            ) catch |err| return mapVeyraArrayError(err);
        }

        fn matvecF64(self: Self, vector: Self) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense matvec fast path requires Array(f64)");
            if (self.shape.len != 2) return error.NonMatrixArray;
            if (vector.shape.len != 1) return error.NonVectorArray;
            if (self.shape[1] != vector.shape[0]) return error.ShapeMismatch;
            if (!self.isContiguous() or !vector.isContiguous()) return error.InvalidShape;

            var out = try Self.zeros(self.allocator, &.{self.shape[0]});
            errdefer out.deinit();
            const lhs = try self.veyraMatrixViewF64();
            const rhs = try vector.veyraVectorViewF64();
            const dst = veyra.VectorMut(f64).fromSlice(out.data);
            veyra.matvec(f64, lhs, rhs, dst) catch |err| return mapVeyraArrayError(err);
            return out;
        }

        fn vecmatF64(self: Self, matrix: Self) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense vector-matrix fast path requires Array(f64)");
            if (self.shape.len != 1) return error.NonVectorArray;
            if (matrix.shape.len != 2) return error.NonMatrixArray;
            if (self.shape[0] != matrix.shape[0]) return error.ShapeMismatch;
            if (!self.isContiguous() or !matrix.isContiguous()) return error.InvalidShape;

            var out = try Self.zeros(self.allocator, &.{matrix.shape[1]});
            errdefer out.deinit();
            const lhs = try matrix.veyraMatrixViewF64();
            const rhs = try self.veyraVectorViewF64();
            const dst = veyra.VectorMut(f64).fromSlice(out.data);
            veyra.gemv(f64, lhs, rhs, dst, .{ .transpose_lhs = .transpose }) catch |err| return mapVeyraArrayError(err);
            return out;
        }

        fn dotF64(self: Self, other: Self) ArrayError!Self {
            if (comptime T != f64) @compileError("Veyra dense dot fast path requires Array(f64)");
            if (self.shape.len != 1 or other.shape.len != 1) return error.NonVectorArray;
            if (self.shape[0] != other.shape[0]) return error.ShapeMismatch;
            if (!self.isContiguous() or !other.isContiguous()) return error.InvalidShape;
            const lhs = try self.veyraVectorViewF64();
            const rhs = try other.veyraVectorViewF64();
            const result = veyra.dot(f64, lhs, rhs) catch |err| return mapVeyraArrayError(err);
            return Self.fromSlice(self.allocator, &.{result}, &.{});
        }

        pub fn det(self: Self) ArrayError!T {
            if (comptime @typeInfo(T) != .float) @compileError("det requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryDetF32(self)) |value| return value;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryDetF64(self)) |value| return value;
            }
            if (comptime T == f64) {
                var matrix = try self.toVeyraMatrixF64();
                defer matrix.deinit();
                var factorization = veyra.lu(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
                defer factorization.deinit();
                return factorization.determinant() catch |err| return mapVeyraArrayError(err);
            }

            const n = self.shape[0];
            var matrix_data = try self.allocator.dupe(T, self.data);
            defer self.allocator.free(matrix_data);
            var det_sign = one(T);
            var result = one(T);
            for (0..n) |i| {
                var pivot = i;
                var pivot_abs = @abs(matrix_data[i * n + i]);
                for (i + 1..n) |r| {
                    const candidate = @abs(matrix_data[r * n + i]);
                    if (candidate > pivot_abs) {
                        pivot_abs = candidate;
                        pivot = r;
                    }
                }
                if (pivot_abs == zero(T)) return zero(T);
                if (pivot != i) {
                    for (0..n) |c| std.mem.swap(T, &matrix_data[i * n + c], &matrix_data[pivot * n + c]);
                    det_sign = -det_sign;
                }
                const pivot_diag = matrix_data[i * n + i];
                result *= pivot_diag;
                for (i + 1..n) |r| {
                    const factor = matrix_data[r * n + i] / pivot_diag;
                    for (i..n) |c| matrix_data[r * n + c] -= factor * matrix_data[i * n + c];
                }
            }
            return result * det_sign;
        }

        pub fn inverse(self: Self) ArrayError!Self {
            if (comptime @typeInfo(T) != .float) @compileError("inverse requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryInverseF32(self)) |out| return out;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryInverseF64(self)) |out| return out;
            }
            if (comptime T == f64) {
                var matrix = try self.toVeyraMatrixF64();
                defer matrix.deinit();
                var inverse_matrix = veyra.inverse(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
                defer inverse_matrix.deinit();
                return Self.fromVeyraMatrixF64(self.allocator, &inverse_matrix);
            }

            const n = self.shape[0];
            var augmented = try self.allocator.alloc(T, n * n * 2);
            defer self.allocator.free(augmented);
            for (0..n) |r| {
                for (0..n) |c| {
                    augmented[r * (2 * n) + c] = self.data[r * n + c];
                    augmented[r * (2 * n) + n + c] = if (r == c) one(T) else zero(T);
                }
            }
            for (0..n) |i| {
                var pivot = i;
                var pivot_abs = @abs(augmented[i * (2 * n) + i]);
                for (i + 1..n) |r| {
                    const candidate = @abs(augmented[r * (2 * n) + i]);
                    if (candidate > pivot_abs) {
                        pivot_abs = candidate;
                        pivot = r;
                    }
                }
                if (pivot_abs == zero(T)) return error.SingularMatrix;
                if (pivot != i) {
                    for (0..2 * n) |c| std.mem.swap(T, &augmented[i * (2 * n) + c], &augmented[pivot * (2 * n) + c]);
                }
                const pivot_diag = augmented[i * (2 * n) + i];
                for (0..2 * n) |c| augmented[i * (2 * n) + c] /= pivot_diag;
                for (0..n) |r| {
                    if (r == i) continue;
                    const factor = augmented[r * (2 * n) + i];
                    for (0..2 * n) |c| augmented[r * (2 * n) + c] -= factor * augmented[i * (2 * n) + c];
                }
            }

            var out = try Self.empty(self.allocator, &.{ n, n });
            errdefer out.deinit();
            for (0..n) |r| {
                for (0..n) |c| out.data[r * n + c] = augmented[r * (2 * n) + n + c];
            }
            return out;
        }

        pub fn inv(self: Self) ArrayError!Self {
            return self.inverse();
        }

        pub fn solve(self: Self, rhs: Self) ArrayError!Self {
            if (comptime @typeInfo(T) != .float) @compileError("solve requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (rhs.shape.len != 1 and rhs.shape.len != 2) return error.InvalidShape;
            if (rhs.shape[0] != self.shape[0]) return error.ShapeMismatch;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.trySolveF32(self, rhs)) |out| return out;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.trySolveF64(self, rhs)) |out| return out;
            }
            if (comptime T == f64) {
                var matrix = try self.toVeyraMatrixF64();
                defer matrix.deinit();
                var factorization = veyra.lu(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
                defer factorization.deinit();
                if (rhs.shape.len == 1) {
                    var rhs_vector = try rhs.toVeyraVectorF64();
                    defer rhs_vector.deinit();
                    var dst_vector = veyra.Vector(f64).zeros(self.allocator, self.shape[1]) catch |err| return mapVeyraArrayError(err);
                    defer dst_vector.deinit();
                    factorization.solve(rhs_vector.asView(), dst_vector.asMut()) catch |err| return mapVeyraArrayError(err);
                    return Self.fromVeyraVectorF64(self.allocator, &dst_vector);
                }
                var rhs_matrix = try rhs.toVeyraMatrixF64();
                defer rhs_matrix.deinit();
                var dst_matrix = veyra.Matrix(f64).zeros(self.allocator, self.shape[1], rhs.shape[1], .row_major) catch |err| return mapVeyraArrayError(err);
                defer dst_matrix.deinit();
                factorization.solveMatrix(rhs_matrix.asView(), dst_matrix.asMut()) catch |err| return mapVeyraArrayError(err);
                return Self.fromVeyraMatrixF64(self.allocator, &dst_matrix);
            }

            var inv_self = try self.inverse();
            defer inv_self.deinit();
            return inv_self.matmul(rhs);
        }

        pub fn cholesky(self: Self) ArrayError!Self {
            if (comptime @typeInfo(T) != .float) @compileError("cholesky requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryCholeskyF32(self)) |out| return out;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryCholeskyF64(self)) |out| return out;
            }
            if (comptime T == f64) {
                var matrix = try self.toVeyraMatrixF64();
                defer matrix.deinit();
                var factorization = veyra.cholesky(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
                defer factorization.deinit();
                var out = try Self.zeros(self.allocator, &.{ self.shape[0], self.shape[1] });
                errdefer out.deinit();
                const lower = factorization.lView();
                for (0..self.shape[0]) |r| {
                    for (0..r + 1) |c| out.data[r * self.shape[1] + c] = lower.get(r, c);
                }
                return out;
            }

            const n = self.shape[0];
            var out = try Self.zeros(self.allocator, &.{ n, n });
            errdefer out.deinit();
            for (0..n) |i| {
                for (0..i + 1) |j| {
                    var sum_value = zero(T);
                    for (0..j) |k| sum_value += out.data[i * n + k] * out.data[j * n + k];
                    if (i == j) {
                        const value = self.data[i * n + i] - sum_value;
                        if (!(value > zero(T))) return error.NotPositiveDefinite;
                        out.data[i * n + j] = std.math.sqrt(value);
                    } else {
                        const denom = out.data[j * n + j];
                        if (denom == zero(T)) return error.NotPositiveDefinite;
                        out.data[i * n + j] = (self.data[i * n + j] - sum_value) / denom;
                    }
                }
            }
            return out;
        }

        pub fn qr(self: Self) ArrayError!QrResult(T) {
            if (comptime @typeInfo(T) != .float) @compileError("qr requires floating-point arrays");
            if (self.shape.len != 2) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryQrF32(self)) |out| return .{ .q = out.q, .r = out.r };
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryQrF64(self)) |out| return .{ .q = out.q, .r = out.r };
            }
            if (comptime T == f64) return self.qrF64();
            return self.qrReference();
        }

        fn qrF64(self: Self) ArrayError!QrResult(T) {
            var matrix = try self.toVeyraMatrixF64();
            defer matrix.deinit();
            var factorization = veyra.qr(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
            defer factorization.deinit();

            var identity_matrix = veyra.Matrix(f64).identity(self.allocator, self.shape[0], .row_major) catch |err| return mapVeyraArrayError(err);
            defer identity_matrix.deinit();
            var q_matrix = veyra.Matrix(f64).zeros(self.allocator, self.shape[0], self.shape[0], .row_major) catch |err| return mapVeyraArrayError(err);
            defer q_matrix.deinit();
            factorization.applyQMatrix(identity_matrix.asView(), q_matrix.asMut()) catch |err| return mapVeyraArrayError(err);

            var q = try Self.fromVeyraMatrixF64(self.allocator, &q_matrix);
            errdefer q.deinit();
            var r = try Self.zeros(self.allocator, &.{ self.shape[0], self.shape[1] });
            errdefer r.deinit();
            const r_view = factorization.rView();
            for (0..self.shape[0]) |row| {
                for (row..self.shape[1]) |col| {
                    if (row < r_view.rows and col < r_view.cols) r.data[row * self.shape[1] + col] = r_view.get(row, col);
                }
            }
            return .{ .q = q, .r = r };
        }

        fn qrReference(self: Self) ArrayError!QrResult(T) {
            const m = self.shape[0];
            const n = self.shape[1];
            var q = try Self.zeros(self.allocator, &.{ m, m });
            errdefer q.deinit();
            var r = try Self.zeros(self.allocator, &.{ m, n });
            errdefer r.deinit();

            for (0..m) |basis_col| {
                for (0..m) |row| q.data[row * m + basis_col] = if (row == basis_col) one(T) else zero(T);
            }
            for (0..n) |j| {
                for (0..m) |row| q.data[row * m + j] = self.data[row * n + j];
                for (0..j) |i| {
                    var dot_value = zero(T);
                    for (0..m) |row| dot_value += q.data[row * m + i] * self.data[row * n + j];
                    r.data[i * n + j] = dot_value;
                    for (0..m) |row| q.data[row * m + j] -= dot_value * q.data[row * m + i];
                }
                var norm_sq = zero(T);
                for (0..m) |row| norm_sq += q.data[row * m + j] * q.data[row * m + j];
                if (norm_sq == zero(T)) return error.SingularMatrix;
                const norm_value = std.math.sqrt(norm_sq);
                r.data[j * n + j] = norm_value;
                for (0..m) |row| q.data[row * m + j] /= norm_value;
            }
            return .{ .q = q, .r = r };
        }

        pub fn lu(self: Self) ArrayError!LuResult(T) {
            if (comptime @typeInfo(T) != .float) @compileError("lu requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryLuF32(self)) |out| return .{ .p = out.p, .l = out.l, .u = out.u };
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryLuF64(self)) |out| return .{ .p = out.p, .l = out.l, .u = out.u };
            }
            if (comptime T == f64) return self.luF64();
            return self.luReference();
        }

        fn luF64(self: Self) ArrayError!LuResult(T) {
            var matrix = try self.toVeyraMatrixF64();
            defer matrix.deinit();
            var factorization = veyra.lu(f64, self.allocator, matrix.asView()) catch |err| return mapVeyraArrayError(err);
            defer factorization.deinit();
            const n = self.shape[0];
            var p = try Self.zeros(self.allocator, &.{ n, n });
            errdefer p.deinit();
            var l = try Self.zeros(self.allocator, &.{ n, n });
            errdefer l.deinit();
            var u = try Self.zeros(self.allocator, &.{ n, n });
            errdefer u.deinit();
            const permutation_view = factorization.permutationView();
            const factors = factorization.factors.asView();
            for (0..n) |r_idx| {
                p.data[r_idx * n + permutation_view.get(r_idx)] = one(T);
                l.data[r_idx * n + r_idx] = one(T);
                for (0..n) |c_idx| {
                    if (r_idx > c_idx) {
                        l.data[r_idx * n + c_idx] = factors.get(r_idx, c_idx);
                    } else {
                        u.data[r_idx * n + c_idx] = factors.get(r_idx, c_idx);
                    }
                }
            }
            return .{ .p = p, .l = l, .u = u };
        }

        fn luReference(self: Self) ArrayError!LuResult(T) {
            const n = self.shape[0];
            var p = try Self.zeros(self.allocator, &.{ n, n });
            errdefer p.deinit();
            var l = try Self.zeros(self.allocator, &.{ n, n });
            errdefer l.deinit();
            var u = try self.clone();
            errdefer u.deinit();
            for (0..n) |i| {
                p.data[i * n + i] = one(T);
                l.data[i * n + i] = one(T);
            }
            for (0..n) |k| {
                var pivot = k;
                var pivot_abs = @abs(u.data[k * n + k]);
                for (k + 1..n) |r_idx| {
                    const candidate = @abs(u.data[r_idx * n + k]);
                    if (candidate > pivot_abs) {
                        pivot_abs = candidate;
                        pivot = r_idx;
                    }
                }
                if (pivot_abs == zero(T)) return error.SingularMatrix;
                if (pivot != k) {
                    for (0..n) |c_idx| {
                        std.mem.swap(T, &u.data[k * n + c_idx], &u.data[pivot * n + c_idx]);
                        std.mem.swap(T, &p.data[k * n + c_idx], &p.data[pivot * n + c_idx]);
                        if (c_idx < k) std.mem.swap(T, &l.data[k * n + c_idx], &l.data[pivot * n + c_idx]);
                    }
                }
                for (k + 1..n) |r_idx| {
                    const factor = u.data[r_idx * n + k] / u.data[k * n + k];
                    l.data[r_idx * n + k] = factor;
                    for (k..n) |c_idx| u.data[r_idx * n + c_idx] -= factor * u.data[k * n + c_idx];
                }
            }
            return .{ .p = p, .l = l, .u = u };
        }

        pub fn solveTriangular(self: Self, rhs: Self, triangle: Triangle, diagonal_kind: Diagonal) ArrayError!Self {
            if (comptime @typeInfo(T) != .float) @compileError("solveTriangular requires floating-point arrays");
            if (self.shape.len != 2 or self.shape[0] != self.shape[1]) return error.NonMatrixArray;
            if (rhs.shape.len != 1 and rhs.shape.len != 2) return error.InvalidShape;
            if (rhs.shape[0] != self.shape[0]) return error.ShapeMismatch;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.trySolveTriangularF32(self, rhs, triangle, diagonal_kind)) |out| return out;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.trySolveTriangularF64(self, rhs, triangle, diagonal_kind)) |out| return out;
            }
            if (comptime T == f64) return self.solveTriangularF64(rhs, triangle, diagonal_kind);
            return self.solveTriangularReference(rhs, triangle, diagonal_kind);
        }

        pub fn solve_triangular(self: Self, rhs: Self, triangle: Triangle, diagonal_kind: Diagonal) ArrayError!Self {
            return self.solveTriangular(rhs, triangle, diagonal_kind);
        }

        fn solveTriangularF64(self: Self, rhs: Self, triangle: Triangle, diagonal_kind: Diagonal) ArrayError!Self {
            var triangular_matrix = try self.toVeyraMatrixF64();
            defer triangular_matrix.deinit();
            const options: veyra.dense.TriangularSolveOptions = .{ .triangle = toVeyraTriangle(triangle), .diagonal = toVeyraDiagonal(diagonal_kind) };

            if (rhs.shape.len == 1) {
                var rhs_vector = try rhs.toVeyraVectorF64();
                defer rhs_vector.deinit();
                var dst_vector = veyra.Vector(f64).zeros(self.allocator, self.shape[0]) catch |err| return mapVeyraArrayError(err);
                defer dst_vector.deinit();
                veyra.dense.solveTriangular(f64, triangular_matrix.asView(), rhs_vector.asView(), dst_vector.asMut(), options) catch |err| return mapVeyraArrayError(err);
                return Self.fromVeyraVectorF64(self.allocator, &dst_vector);
            }

            var rhs_matrix = try rhs.toVeyraMatrixF64();
            defer rhs_matrix.deinit();
            var dst_matrix = veyra.Matrix(f64).zeros(self.allocator, self.shape[0], rhs.shape[1], .row_major) catch |err| return mapVeyraArrayError(err);
            defer dst_matrix.deinit();
            veyra.dense.solveTriangularMatrix(f64, triangular_matrix.asView(), rhs_matrix.asView(), dst_matrix.asMut(), options) catch |err| return mapVeyraArrayError(err);
            return Self.fromVeyraMatrixF64(self.allocator, &dst_matrix);
        }

        fn solveTriangularReference(self: Self, rhs: Self, triangle: Triangle, diagonal_kind: Diagonal) ArrayError!Self {
            if (rhs.shape.len == 1) {
                var out = try Self.zeros(self.allocator, &.{self.shape[0]});
                errdefer out.deinit();
                try self.solveTriangularVectorReference(rhs.data, out.data, triangle, diagonal_kind);
                return out;
            }

            var out = try Self.zeros(self.allocator, &.{ self.shape[0], rhs.shape[1] });
            errdefer out.deinit();
            for (0..rhs.shape[1]) |col| {
                const rhs_col = try self.allocator.alloc(T, self.shape[0]);
                defer self.allocator.free(rhs_col);
                const dst_col = try self.allocator.alloc(T, self.shape[0]);
                defer self.allocator.free(dst_col);
                for (0..self.shape[0]) |row| rhs_col[row] = rhs.data[row * rhs.shape[1] + col];
                try self.solveTriangularVectorReference(rhs_col, dst_col, triangle, diagonal_kind);
                for (0..self.shape[0]) |row| out.data[row * rhs.shape[1] + col] = dst_col[row];
            }
            return out;
        }

        fn solveTriangularVectorReference(self: Self, rhs: []const T, out: []T, triangle: Triangle, diagonal_kind: Diagonal) ArrayError!void {
            const n = self.shape[0];
            switch (triangle) {
                .lower => {
                    for (0..n) |i| {
                        var acc = rhs[i];
                        for (0..i) |j| acc -= self.data[i * n + j] * out[j];
                        if (diagonal_kind == .non_unit) {
                            const diagonal_value = self.data[i * n + i];
                            if (diagonal_value == zero(T)) return error.SingularMatrix;
                            acc /= diagonal_value;
                        }
                        out[i] = acc;
                    }
                },
                .upper => {
                    var i = n;
                    while (i > 0) {
                        i -= 1;
                        var acc = rhs[i];
                        for (i + 1..n) |j| acc -= self.data[i * n + j] * out[j];
                        if (diagonal_kind == .non_unit) {
                            const diagonal_value = self.data[i * n + i];
                            if (diagonal_value == zero(T)) return error.SingularMatrix;
                            acc /= diagonal_value;
                        }
                        out[i] = acc;
                    }
                },
            }
        }

        pub fn svd(self: Self, tolerance: T) ArrayError!SvdResult(T) {
            if (comptime @typeInfo(T) != .float) @compileError("svd requires floating-point arrays");
            if (self.shape.len != 2) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.trySvdF32(self, tolerance)) |out| return .{ .u = out.u, .s = out.s, .vt = out.vt };
                return error.BackendFailure;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.trySvdF64(self, tolerance)) |out| return .{ .u = out.u, .s = out.s, .vt = out.vt };
            } else {
                return error.BackendFailure;
            }

            var matrix = try self.toVeyraMatrixF64();
            defer matrix.deinit();
            var decomposition = veyra.svdViaEigen(f64, self.allocator, matrix.asView(), tolerance) catch |err| return mapVeyraArrayError(err);
            defer decomposition.deinit();
            var u = try Self.fromVeyraMatrixF64(self.allocator, &decomposition.u);
            errdefer u.deinit();
            var s_values = try Self.fromVeyraVectorF64(self.allocator, &decomposition.singular_values);
            errdefer s_values.deinit();
            var vt = try Self.fromVeyraMatrixF64(self.allocator, &decomposition.vt);
            errdefer vt.deinit();
            return .{ .u = u, .s = s_values, .vt = vt };
        }

        pub fn singularValues(self: Self, tolerance: T) ArrayError!Self {
            if (comptime @typeInfo(T) != .float) @compileError("singularValues requires floating-point arrays");
            if (self.shape.len != 2) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.trySingularValuesF32(self, tolerance)) |out| return out;
                return error.BackendFailure;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.trySingularValuesF64(self, tolerance)) |out| return out;
            } else {
                return error.BackendFailure;
            }

            var factors = try self.svd(tolerance);
            defer factors.deinit();
            return factors.s.clone();
        }

        pub fn singular_values(self: Self, tolerance: T) ArrayError!Self {
            return self.singularValues(tolerance);
        }

        pub fn matrixRank(self: Self, tolerance: T) ArrayError!usize {
            if (comptime @typeInfo(T) != .float) @compileError("matrixRank requires floating-point arrays");
            if (self.shape.len != 2) return error.NonMatrixArray;
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryMatrixRankF32(self, tolerance)) |value| return value;
                return error.BackendFailure;
            } else if (comptime T == f64) {
                if (try axiom_cpu_backend.tryMatrixRankF64(self, tolerance)) |value| return value;
                return error.BackendFailure;
            } else {
                return error.BackendFailure;
            }
        }

        pub fn matrix_rank(self: Self, tolerance: T) ArrayError!usize {
            return self.matrixRank(tolerance);
        }

