        pub fn isContiguous(self: Self) bool {
            var expected: usize = 1;
            var i = self.shape.len;
            while (i > 0) {
                i -= 1;
                if (self.strides[i] != expected) return false;
                expected *= self.shape[i];
            }
            return true;
        }

