        pub fn countNonzero(self: Self) usize {
            var count: usize = 0;
            for (self.data) |v| {
                if (v != zero(T)) count += 1;
            }
            return count;
        }

        pub fn count_nonzero(self: Self) usize {
            return self.countNonzero();
        }

        pub fn countNonzeroAxis(self: Self, axis_opt: ?isize, keepdims: bool) ArrayError!Array(usize) {
            if (axis_opt == null) {
                const count = self.countNonzero();
                if (keepdims) {
                    const out_shape = try keepDimsAllOnes(self.allocator, self.shape.len);
                    defer self.allocator.free(out_shape);
                    return Array(usize).fromSlice(self.allocator, &.{count}, out_shape);
                }
                return Array(usize).fromSlice(self.allocator, &.{count}, &.{});
            }

            const axis = try normalizeDim(axis_opt.?, self.shape.len);
            const out_shape = try self.reducedShape(axis, keepdims);
            defer self.allocator.free(out_shape);
            var out = try Array(usize).zeros(self.allocator, out_shape);
            errdefer out.deinit();
            if (self.data.len == 0) return out;

            const in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);
            var out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            for (self.data, 0..) |value, flat| {
                if (value == zero(T)) continue;
                unravelIndexInto(flat, self.shape, in_multi);
                if (keepdims) {
                    @memcpy(out_multi, in_multi);
                    out_multi[axis] = 0;
                } else {
                    for (in_multi[0..axis], 0..) |coord, i| out_multi[i] = coord;
                    for (in_multi[axis + 1 ..], axis..) |coord, i| out_multi[i] = coord;
                }
                out.data[ravelIndex(out_multi, out.strides)] += 1;
            }
            return out;
        }

        pub fn countNonzeroAxes(self: Self, axes: []const isize, keepdims: bool) ArrayError!Array(usize) {
            if (axes.len == 0) {
                var values = try Array(usize).empty(self.allocator, self.shape);
                errdefer values.deinit();
                for (self.data, values.data) |value, *slot| slot.* = if (value == zero(T)) 0 else 1;
                return values;
            }
            const normalized_axes = try normalizeAxesDescending(self.allocator, axes, self.shape.len);
            defer self.allocator.free(normalized_axes);
            var current = try self.countNonzeroAxis(@intCast(normalized_axes[0]), keepdims);
            errdefer current.deinit();
            for (normalized_axes[1..]) |axis| {
                const next = try current.sum(@intCast(axis), keepdims);
                current.deinit();
                current = next;
            }
            return current;
        }

        pub fn count_nonzero_axes(self: Self, axes: []const isize, keepdims: bool) ArrayError!Array(usize) {
            return self.countNonzeroAxes(axes, keepdims);
        }

        pub fn countNonzeroDim(self: Self, dim_opt: ?isize, keepdim: bool) ArrayError!Array(usize) {
            return self.countNonzeroAxis(dim_opt, keepdim);
        }

        pub fn count_nonzero_dim(self: Self, dim_opt: ?isize, keepdim: bool) ArrayError!Array(usize) {
            return self.countNonzeroDim(dim_opt, keepdim);
        }

        pub fn countNonzeroDims(self: Self, dims: []const isize, keepdim: bool) ArrayError!Array(usize) {
            return self.countNonzeroAxes(dims, keepdim);
        }

        pub fn count_nonzero_dims(self: Self, dims: []const isize, keepdim: bool) ArrayError!Array(usize) {
