        pub fn compress(self: Self, condition: Array(bool), axis_opt: ?isize) ArrayError!Self {
            if (condition.shape.len != 1) return error.ShapeMismatch;
            if (axis_opt == null) {
                var flat = try self.flatten();
                defer flat.deinit();
                if (condition.data.len != flat.data.len) return error.ShapeMismatch;
                return flat.maskedSelect(condition);
            }

            const axis = try normalizeDim(axis_opt.?, self.shape.len);
            if (condition.data.len != self.shape[axis]) return error.ShapeMismatch;
            var selected_count: usize = 0;
            for (condition.data) |keep| {
                if (keep) selected_count += 1;
            }
            const selected = try self.allocator.alloc(usize, selected_count);
            defer self.allocator.free(selected);
            var write: usize = 0;
            for (condition.data, 0..) |keep, i| {
                if (keep) {
                    selected[write] = i;
                    write += 1;
                }
            }

            var out_shape = try self.allocator.dupe(usize, self.shape);
            defer self.allocator.free(out_shape);
            out_shape[axis] = selected_count;
            const out = try Self.empty(self.allocator, out_shape);
            if (out.data.len == 0) return out;
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            var in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);
            for (out.data, 0..) |*slot, flat| {
                unravelIndexInto(flat, out_shape, out_multi);
                @memcpy(in_multi, out_multi);
                in_multi[axis] = selected[out_multi[axis]];
                slot.* = self.data[ravelIndex(in_multi, self.strides)];
            }
            return out;
        }

        pub fn gather(self: Self, axis_index: isize, indices: Array(usize)) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (indices.shape.len != self.shape.len) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }

            var out = try Self.empty(self.allocator, indices.shape);
            errdefer out.deinit();
            if (out.data.len == 0) return out;
            const out_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(out_multi);
            var in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);

            for (out.data, 0..) |*slot, flat| {
                unravelIndexInto(flat, indices.shape, out_multi);
                const selected = indices.data[flat];
                if (selected >= self.shape[axis]) return error.IndexOutOfBounds;
                @memcpy(in_multi, out_multi);
                in_multi[axis] = selected;
                slot.* = self.data[ravelIndex(in_multi, self.strides)];
            }
            return out;
        }

        pub fn gatherSigned(self: Self, axis_index: isize, indices: Array(isize)) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (indices.shape.len != self.shape.len) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }
            var out = try Self.empty(self.allocator, indices.shape);
            errdefer out.deinit();
            if (out.data.len == 0) return out;
            const out_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(out_multi);
            var in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);
            for (out.data, 0..) |*slot, flat| {
                unravelIndexInto(flat, indices.shape, out_multi);
                @memcpy(in_multi, out_multi);
                in_multi[axis] = try normalizeIndex(indices.data[flat], self.shape[axis]);
                slot.* = self.data[ravelIndex(in_multi, self.strides)];
            }
            return out;
        }

        pub fn gather_signed(self: Self, axis_index: isize, indices: Array(isize)) ArrayError!Self {
            return self.gatherSigned(axis_index, indices);
        }

        pub fn scatter(self: Self, axis_index: isize, indices: Array(usize), src: Self) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (!std.mem.eql(usize, indices.shape, src.shape)) return error.ShapeMismatch;
            if (indices.shape.len != self.shape.len) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }

            var out = try self.clone();
            errdefer out.deinit();
            if (indices.data.len == 0) return out;
            const src_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(src_multi);
            var dst_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(dst_multi);

            for (src.data, 0..) |value, flat| {
                unravelIndexInto(flat, indices.shape, src_multi);
                const selected = indices.data[flat];
                if (selected >= self.shape[axis]) return error.IndexOutOfBounds;
                @memcpy(dst_multi, src_multi);
                dst_multi[axis] = selected;
                out.data[ravelIndex(dst_multi, out.strides)] = value;
            }
            return out;
        }

        pub fn scatterScalar(self: Self, axis_index: isize, indices: Array(usize), value: T) ArrayError!Self {
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (indices.shape.len != self.shape.len) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }

            var out = try self.clone();
            errdefer out.deinit();
            if (indices.data.len == 0) return out;
            const idx_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(idx_multi);
            var dst_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(dst_multi);

            for (indices.data, 0..) |selected, flat| {
                if (selected >= self.shape[axis]) return error.IndexOutOfBounds;
                unravelIndexInto(flat, indices.shape, idx_multi);
                @memcpy(dst_multi, idx_multi);
                dst_multi[axis] = selected;
                out.data[ravelIndex(dst_multi, out.strides)] = value;
            }
            return out;
        }

        fn validateScatterShapes(self: Self, axis: usize, indices: Array(usize), src_shape: []const usize) ArrayError!void {
            if (indices.shape.len != self.shape.len or src_shape.len != self.shape.len) return error.ShapeMismatch;
            if (!std.mem.eql(usize, indices.shape, src_shape)) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }
        }

        fn applyScatterReduce(current: T, value: T, reduction: ScatterReduce) T {
            return switch (reduction) {
                .sum => addValue(T, current, value),
                .prod => mulValue(T, current, value),
                .min => if (value < current) value else current,
                .max => if (value > current) value else current,
            };
        }

        pub fn scatterReduce(self: Self, axis_index: isize, indices: Array(usize), src: Self, reduction: ScatterReduce) ArrayError!Self {
            ensureNumeric(T);
            const axis = try normalizeDim(axis_index, self.shape.len);
            try self.validateScatterShapes(axis, indices, src.shape);

            var out = try self.clone();
            errdefer out.deinit();
            if (indices.data.len == 0) return out;
            const src_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(src_multi);
            var dst_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(dst_multi);

            for (src.data, 0..) |value, flat| {
                unravelIndexInto(flat, indices.shape, src_multi);
                const selected = indices.data[flat];
                if (selected >= self.shape[axis]) return error.IndexOutOfBounds;
                @memcpy(dst_multi, src_multi);
                dst_multi[axis] = selected;
                const out_index = ravelIndex(dst_multi, out.strides);
                out.data[out_index] = applyScatterReduce(out.data[out_index], value, reduction);
            }
            return out;
        }

        pub fn scatterAdd(self: Self, axis_index: isize, indices: Array(usize), src: Self) ArrayError!Self {
            return self.scatterReduce(axis_index, indices, src, .sum);
        }

        pub fn scatterReduceScalar(self: Self, axis_index: isize, indices: Array(usize), value: T, reduction: ScatterReduce) ArrayError!Self {
            ensureNumeric(T);
            const axis = try normalizeDim(axis_index, self.shape.len);
            if (indices.shape.len != self.shape.len) return error.ShapeMismatch;
            for (indices.shape, self.shape, 0..) |index_dim, self_dim, i| {
                if (i != axis and index_dim > self_dim) return error.ShapeMismatch;
            }

            var out = try self.clone();
            errdefer out.deinit();
            if (indices.data.len == 0) return out;
            const idx_multi = try self.allocator.alloc(usize, indices.shape.len);
            defer self.allocator.free(idx_multi);
            var dst_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(dst_multi);

            for (indices.data, 0..) |selected, flat| {
                if (selected >= self.shape[axis]) return error.IndexOutOfBounds;
                unravelIndexInto(flat, indices.shape, idx_multi);
                @memcpy(dst_multi, idx_multi);
                dst_multi[axis] = selected;
                const out_index = ravelIndex(dst_multi, out.strides);
                out.data[out_index] = applyScatterReduce(out.data[out_index], value, reduction);
            }
            return out;
        }

        pub fn scatterAddScalar(self: Self, axis_index: isize, indices: Array(usize), value: T) ArrayError!Self {
            return self.scatterReduceScalar(axis_index, indices, value, .sum);
        }

        fn binaryArraySimdLanes(
            comptime lanes: usize,
            out: []T,
            lhs: []const T,
            rhs: []const T,
            comptime op: fn (T, T) T,
        ) bool {
            const Vec = @Vector(lanes, T);
            var i: usize = 0;
            if (comptime op == opAdd) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = lhs[i..][0..lanes].*;
                    const b0: Vec = rhs[i..][0..lanes].*;
                    const a1: Vec = lhs[i + lanes ..][0..lanes].*;
                    const b1: Vec = rhs[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 + b0;
                    out[i + lanes ..][0..lanes].* = a1 + b1;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a + b;
                }
            } else if (comptime op == opSub) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = lhs[i..][0..lanes].*;
                    const b0: Vec = rhs[i..][0..lanes].*;
                    const a1: Vec = lhs[i + lanes ..][0..lanes].*;
                    const b1: Vec = rhs[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 - b0;
                    out[i + lanes ..][0..lanes].* = a1 - b1;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a - b;
                }
            } else if (comptime op == opMul) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = lhs[i..][0..lanes].*;
                    const b0: Vec = rhs[i..][0..lanes].*;
                    const a1: Vec = lhs[i + lanes ..][0..lanes].*;
                    const b1: Vec = rhs[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 * b0;
                    out[i + lanes ..][0..lanes].* = a1 * b1;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a * b;
                }
            } else if (comptime op == opDiv) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = lhs[i..][0..lanes].*;
                    const b0: Vec = rhs[i..][0..lanes].*;
                    const a1: Vec = lhs[i + lanes ..][0..lanes].*;
                    const b1: Vec = rhs[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 / b0;
                    out[i + lanes ..][0..lanes].* = a1 / b1;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a / b;
                }
            } else {
                return false;
            }
            while (i < out.len) : (i += 1) out[i] = op(lhs[i], rhs[i]);
            return true;
        }

        fn binaryArraySimd(out: []T, lhs: []const T, rhs: []const T, comptime op: fn (T, T) T) bool {
            if (comptime T == f64) return binaryArraySimdLanes(4, out, lhs, rhs, op);
            if (comptime T == f32) return binaryArraySimdLanes(8, out, lhs, rhs, op);
            return false;
        }

        fn binaryScalarSimdLanes(
            comptime lanes: usize,
            out: []T,
            input: []const T,
            scalar: T,
            comptime op: fn (T, T) T,
        ) bool {
            const Vec = @Vector(lanes, T);
            const scalar_vec: Vec = @splat(scalar);
            var i: usize = 0;
            if (comptime op == opAdd) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = input[i..][0..lanes].*;
                    const a1: Vec = input[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 + scalar_vec;
                    out[i + lanes ..][0..lanes].* = a1 + scalar_vec;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a + scalar_vec;
                }
            } else if (comptime op == opSub) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = input[i..][0..lanes].*;
                    const a1: Vec = input[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 - scalar_vec;
                    out[i + lanes ..][0..lanes].* = a1 - scalar_vec;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a - scalar_vec;
                }
            } else if (comptime op == opMul) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = input[i..][0..lanes].*;
                    const a1: Vec = input[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 * scalar_vec;
                    out[i + lanes ..][0..lanes].* = a1 * scalar_vec;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a * scalar_vec;
                }
            } else if (comptime op == opDiv) {
                while (i + lanes * 2 <= out.len) : (i += lanes * 2) {
                    const a0: Vec = input[i..][0..lanes].*;
                    const a1: Vec = input[i + lanes ..][0..lanes].*;
                    out[i..][0..lanes].* = a0 / scalar_vec;
                    out[i + lanes ..][0..lanes].* = a1 / scalar_vec;
                }
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a / scalar_vec;
                }
            } else {
                return false;
            }
            while (i < out.len) : (i += 1) out[i] = op(input[i], scalar);
            return true;
        }

        fn binaryScalarSimd(out: []T, input: []const T, scalar: T, comptime op: fn (T, T) T) bool {
            if (comptime T == f64) return binaryScalarSimdLanes(4, out, input, scalar, op);
            if (comptime T == f32) return binaryScalarSimdLanes(8, out, input, scalar, op);
            return false;
        }

        fn sumFlatSimdLanes(comptime lanes: usize, values: []const T) T {
            const Vec = @Vector(lanes, T);
            var acc0: Vec = @splat(zero(T));
            var acc1: Vec = @splat(zero(T));
            var acc2: Vec = @splat(zero(T));
            var acc3: Vec = @splat(zero(T));
            var i: usize = 0;
            while (i + lanes * 4 <= values.len) : (i += lanes * 4) {
                acc0 += values[i..][0..lanes].*;
                acc1 += values[i + lanes ..][0..lanes].*;
                acc2 += values[i + lanes * 2 ..][0..lanes].*;
                acc3 += values[i + lanes * 3 ..][0..lanes].*;
            }
            while (i + lanes <= values.len) : (i += lanes) {
                acc0 += values[i..][0..lanes].*;
            }

            var total = zero(T);
            inline for (0..lanes) |lane| {
                total += acc0[lane];
                total += acc1[lane];
                total += acc2[lane];
                total += acc3[lane];
            }
            while (i < values.len) : (i += 1) total += values[i];
            return total;
        }

        fn sumFlatValue(self: Self) T {
            if (comptime T == f64) return sumFlatSimdLanes(4, self.data);
            if (comptime T == f32) return sumFlatSimdLanes(8, self.data);
            var total = zero(T);
            for (self.data) |value| total = addValue(T, total, value);
            return total;
        }

        fn scalarReductionResult(self: Self, value: T, keepdims: bool) ArrayError!Self {
            if (keepdims) {
                const out_shape = try keepDimsAllOnes(self.allocator, self.shape.len);
                defer self.allocator.free(out_shape);
                var out = try Self.empty(self.allocator, out_shape);
                out.data[0] = value;
                return out;
            }
            var out = try Self.empty(self.allocator, &.{});
            out.data[0] = value;
            return out;
        }

        fn compareArraySimdLanes(
            comptime lanes: usize,
            out: []bool,
            lhs: []const T,
            rhs: []const T,
            comptime op: fn (T, T) bool,
        ) bool {
            const Vec = @Vector(lanes, T);
            var i: usize = 0;
            if (comptime op == opEqCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a == b;
                }
            } else if (comptime op == opNeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a != b;
                }
            } else if (comptime op == opGtCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = b < a;
                }
            } else if (comptime op == opGeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = !(a < b);
                }
            } else if (comptime op == opLtCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = a < b;
                }
            } else if (comptime op == opLeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = lhs[i..][0..lanes].*;
                    const b: Vec = rhs[i..][0..lanes].*;
                    out[i..][0..lanes].* = !(b < a);
                }
            } else {
                return false;
            }
            while (i < out.len) : (i += 1) out[i] = op(lhs[i], rhs[i]);
            return true;
        }

        fn compareArraySimd(out: []bool, lhs: []const T, rhs: []const T, comptime op: fn (T, T) bool) bool {
            if (comptime T == f64) return compareArraySimdLanes(4, out, lhs, rhs, op);
            if (comptime T == f32) return compareArraySimdLanes(8, out, lhs, rhs, op);
            return false;
        }

        fn compareScalarSimdLanes(
            comptime lanes: usize,
            out: []bool,
            input: []const T,
            scalar: T,
            comptime op: fn (T, T) bool,
        ) bool {
            const Vec = @Vector(lanes, T);
            const scalar_vec: Vec = @splat(scalar);
            var i: usize = 0;
            if (comptime op == opEqCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a == scalar_vec;
                }
            } else if (comptime op == opNeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a != scalar_vec;
                }
            } else if (comptime op == opGtCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = scalar_vec < a;
                }
            } else if (comptime op == opGeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = !(a < scalar_vec);
                }
            } else if (comptime op == opLtCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = a < scalar_vec;
                }
            } else if (comptime op == opLeCompare) {
                while (i + lanes <= out.len) : (i += lanes) {
                    const a: Vec = input[i..][0..lanes].*;
                    out[i..][0..lanes].* = !(scalar_vec < a);
                }
            } else {
                return false;
            }
            while (i < out.len) : (i += 1) out[i] = op(input[i], scalar);
            return true;
        }

        fn compareScalarSimd(out: []bool, input: []const T, scalar: T, comptime op: fn (T, T) bool) bool {
            if (comptime T == f64) return compareScalarSimdLanes(4, out, input, scalar, op);
            if (comptime T == f32) return compareScalarSimdLanes(8, out, input, scalar, op);
            return false;
        }

        fn binaryArrayOut(self: Self, other: Self, out: Self, comptime op: fn (T, T) T) ArrayError!void {
            if (std.mem.eql(usize, self.shape, other.shape)) {
                if (!std.mem.eql(usize, out.shape, self.shape)) return error.ShapeMismatch;
                if (binaryArraySimd(out.data, self.data, other.data, op)) return;
                for (self.data, other.data, out.data) |lhs, rhs, *slot| {
                    slot.* = op(lhs, rhs);
                }
                return;
            }
            const out_shape = try computeBroadcastShape(self.allocator, self.shape, other.shape);
            defer self.allocator.free(out_shape);
            if (!std.mem.eql(usize, out.shape, out_shape)) return error.ShapeMismatch;

            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);

            for (out.data, 0..) |*slot, i| {
                unravelIndexInto(i, out_shape, out_multi);
                const ai = broadcastOffset(out_multi, out_shape.len, self.shape, self.strides);
                const bi = broadcastOffset(out_multi, out_shape.len, other.shape, other.strides);
                slot.* = op(self.data[ai], other.data[bi]);
            }
        }

        fn pendingCudaMatmul(lhs: Self, rhs: Self, out_shape: []const usize) ArrayError!Self {
            if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return error.TypeUnsupported;
            const lhs_storage = lhs.device_storage orelse return error.InvalidDevice;
            const rhs_storage = rhs.device_storage orelse return error.InvalidDevice;
            const shape = try lhs.allocator.dupe(usize, out_shape);
            errdefer lhs.allocator.free(shape);
            const strides = try stridesFor(lhs.allocator, shape);
            errdefer lhs.allocator.free(strides);
            const values = try lhs.allocator.alloc(T, 0);
            return .{
                .allocator = lhs.allocator,
                .data = values,
                .shape = shape,
                .strides = strides,
                .device = lhs.device,
                .device_storage = null,
                .pending_matmul = .{
                    .lhs_storage = lhs_storage,
                    .rhs_storage = rhs_storage,
                    .lhs_shape = .{ lhs.shape[0], lhs.shape[1] },
                    .rhs_shape = .{ rhs.shape[0], rhs.shape[1] },
                },
            };
        }

        fn materializePendingMatmul(self: Self) ArrayError!Self {
            const pending = self.pending_matmul orelse return self.clone();
            if (pending.unary) |unary_op| {
                if (comptime T == f32) {
                    if (pending.add_storage) |add_storage| {
                        const m = pending.lhs_shape[0];
                        const k = pending.lhs_shape[1];
                        const n = pending.rhs_shape[1];
                        const ops = std.math.mul(usize, std.math.mul(usize, m, n) catch return error.InvalidShape, k) catch return error.InvalidShape;
                        if (self.device.isCuda() and ops <= 4 * 1024 * 1024) {
                            var out = try Self.emptyOn(self.allocator, self.shape, self.device);
                            errdefer out.deinit();
                            const out_storage = out.device_storage orelse return error.InvalidDevice;
                            const ok = try axiom_cuda_backend.runPendingMatmulAddUnaryF32(
                                self.allocator,
                                self.device,
                                switch (unary_op) {
                                    .sqrt => axiom_cuda_backend.UnaryOp.sqrt,
                                    .exp => axiom_cuda_backend.UnaryOp.exp,
                                },
                                m,
                                n,
                                k,
                                pending.lhs_storage.ptr,
                                pending.rhs_storage.ptr,
                                add_storage.ptr,
                                out_storage.ptr,
                                pending.alpha,
                                pending.beta,
                            );
                            if (!ok) return error.BackendFailure;
                            return out;
                        }
                    }
                }
                var without_unary = self;
                without_unary.pending_matmul = pending;
                without_unary.pending_matmul.?.unary = null;
                var materialized = try without_unary.materializePendingMatmul();
                defer materialized.deinit();
                return switch (unary_op) {
                    .sqrt => try materialized.runCudaUnarySqrt(),
                    .exp => try materialized.runCudaUnaryExp(),
                };
            }
            var out = try Self.emptyOn(self.allocator, self.shape, self.device);
            errdefer out.deinit();
            const out_storage = out.device_storage orelse return error.InvalidDevice;
            const m = pending.lhs_shape[0];
            const k = pending.lhs_shape[1];
            const n = pending.rhs_shape[1];
            const ok = if (pending.add_storage) |add_storage| blk: {
                break :blk if (comptime T == f32)
                    try axiom_cuda_backend.runPendingMatmulAddF32(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, add_storage.ptr, out_storage.ptr, pending.alpha, pending.beta)
                else if (comptime T == f64)
                    try axiom_cuda_backend.runPendingMatmulAddF64(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, add_storage.ptr, out_storage.ptr, pending.alpha, pending.beta)
                else if (comptime T == f16)
                    try axiom_cuda_backend.runPendingMatmulAddF16(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, add_storage.ptr, out_storage.ptr, pending.alpha, pending.beta)
                else if (comptime T == BFloat16)
                    try axiom_cuda_backend.runPendingMatmulAddBF16(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, add_storage.ptr, out_storage.ptr, pending.alpha, pending.beta)
                else
                    return error.TypeUnsupported;
            } else blk: {
                break :blk if (comptime T == f32)
                    try axiom_cuda_backend.runPendingMatmulF32(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, out_storage.ptr)
                else if (comptime T == f64)
                    try axiom_cuda_backend.runPendingMatmulF64(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, out_storage.ptr)
                else if (comptime T == f16)
                    try axiom_cuda_backend.runPendingMatmulF16(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, out_storage.ptr)
                else if (comptime T == BFloat16)
                    try axiom_cuda_backend.runPendingMatmulBF16(self.allocator, self.device, m, n, k, pending.lhs_storage.ptr, pending.rhs_storage.ptr, out_storage.ptr)
                else
                    return error.TypeUnsupported;
            };
            if (!ok) return error.BackendFailure;
            return out;
        }

        fn tryFusePendingMatmulAdd(self: Self, other: Self, comptime op: fn (T, T) T) ArrayError!?Self {
            if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return null;
            if (self.pending_matmul == null) return null;
            if (comptime op != opAdd and op != opSub) return null;
            if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
            if (!self.device.isCuda() or !other.device.isCuda() or !self.device.sameDevice(other.device)) return null;
            const pending = self.pending_matmul.?;
            if (pending.add_storage != null) return null;
            const add_storage = other.device_storage orelse return null;
            const shape = try self.allocator.dupe(usize, self.shape);
            errdefer self.allocator.free(shape);
            const strides = try stridesFor(self.allocator, shape);
            errdefer self.allocator.free(strides);
            const values = try self.allocator.alloc(T, 0);
            const beta_value: f32 = if (comptime op == opSub) -1.0 else 1.0;
            return .{
                .allocator = self.allocator,
                .data = values,
                .shape = shape,
                .strides = strides,
                .device = self.device,
                .device_storage = null,
                .pending_matmul = .{
                    .lhs_storage = pending.lhs_storage,
                    .rhs_storage = pending.rhs_storage,
                    .add_storage = add_storage,
                    .lhs_shape = pending.lhs_shape,
                    .rhs_shape = pending.rhs_shape,
                    .beta = beta_value,
                },
            };
        }

        fn tryFusePendingMatmulRSub(self: Self, other: Self) ArrayError!?Self {
            if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return null;
            if (self.pending_matmul == null) return null;
            if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
            if (!self.device.isCuda() or !other.device.isCuda() or !self.device.sameDevice(other.device)) return null;
            const pending = self.pending_matmul.?;
            if (pending.add_storage != null) return null;
            const add_storage = other.device_storage orelse return null;
            const shape = try self.allocator.dupe(usize, self.shape);
            errdefer self.allocator.free(shape);
            const strides = try stridesFor(self.allocator, shape);
            errdefer self.allocator.free(strides);
            const values = try self.allocator.alloc(T, 0);
            return .{
                .allocator = self.allocator,
                .data = values,
                .shape = shape,
                .strides = strides,
                .device = self.device,
                .device_storage = null,
                .pending_matmul = .{
                    .lhs_storage = pending.lhs_storage,
                    .rhs_storage = pending.rhs_storage,
                    .add_storage = add_storage,
                    .lhs_shape = pending.lhs_shape,
                    .rhs_shape = pending.rhs_shape,
                    .alpha = -1.0,
                    .beta = 1.0,
                },
            };
        }

        fn tryPendingUnary(self: Self, unary_op: PendingUnary) ArrayError!?Self {
            if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return null;
            if (!self.device.isCuda() or self.pending_matmul == null) return null;
            var pending = self.pending_matmul.?;
            if (pending.unary != null) return null;
            const shape = try self.allocator.dupe(usize, self.shape);
            errdefer self.allocator.free(shape);
            const strides = try stridesFor(self.allocator, shape);
            errdefer self.allocator.free(strides);
            const values = try self.allocator.alloc(T, 0);
            pending.unary = unary_op;
            return .{
                .allocator = self.allocator,
                .data = values,
                .shape = shape,
                .strides = strides,
                .device = self.device,
                .device_storage = null,
                .pending_matmul = pending,
            };
        }

        fn tryScalePendingMatmul(self: Self, scalar: T, comptime op: fn (T, T) T) ArrayError!?Self {
            if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return null;
            if (!self.device.isCuda() or self.pending_matmul == null) return null;
            if (comptime op != opMul) return null;
            const scale: f32 = if (comptime T == BFloat16) scalar.toF32() else @floatCast(scalar);
            var pending = self.pending_matmul.?;
            if (pending.unary != null) return null;
            pending.alpha *= scale;
            pending.beta *= scale;
            const shape = try self.allocator.dupe(usize, self.shape);
            errdefer self.allocator.free(shape);
            const strides = try stridesFor(self.allocator, shape);
            errdefer self.allocator.free(strides);
            const values = try self.allocator.alloc(T, 0);
            return .{
                .allocator = self.allocator,
                .data = values,
                .shape = shape,
                .strides = strides,
                .device = self.device,
                .device_storage = null,
                .pending_matmul = pending,
            };
        }

        fn runCudaUnarySqrt(self: Self) ArrayError!Self {
            if (comptime T == f32) {
                if (try axiom_cuda_backend.trySqrtF32(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == f16) {
                if (try axiom_cuda_backend.trySqrtF16(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == f64) {
                if (try axiom_cuda_backend.trySqrtF64(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == BFloat16) {
                if (try axiom_cuda_backend.trySqrtBF16(self)) |out| return out;
                return error.BackendFailure;
            }
            return error.TypeUnsupported;
        }

        fn runCudaUnaryExp(self: Self) ArrayError!Self {
            if (comptime T == f32) {
                if (try axiom_cuda_backend.tryExpF32(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == f16) {
                if (try axiom_cuda_backend.tryExpF16(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == BFloat16) {
                if (try axiom_cuda_backend.tryExpBF16(self)) |out| return out;
                return error.BackendFailure;
            }
            if (comptime T == f64) {
                if (try axiom_cuda_backend.tryExpF64(self)) |out| return out;
                return error.BackendFailure;
            }
            return error.TypeUnsupported;
        }

        fn attachCpuMatmulProvenance(out: *Self, lhs: Self, rhs: Self) void {
            if (comptime T != f32 and T != f64) return;
            if (!out.device.isCpu() or !lhs.device.isCpu() or !rhs.device.isCpu()) return;
            if (lhs.shape.len != 2 or rhs.shape.len != 2 or lhs.shape[1] != rhs.shape[0]) return;
            if (!lhs.isContiguous() or !rhs.isContiguous()) return;
            out.cpu_matmul = .{
                .lhs_data = lhs.data,
                .rhs_data = rhs.data,
                .lhs_shape = .{ lhs.shape[0], lhs.shape[1] },
                .rhs_shape = .{ rhs.shape[0], rhs.shape[1] },
            };
        }

        fn attachCpuMatmulDerived(out: *Self, pending: CpuMatmulFusion, alpha_value: f32, beta_value: f32) void {
            if (comptime T != f32 and T != f64) return;
            if (!out.device.isCpu()) return;
            out.cpu_matmul = pending;
            out.cpu_matmul.?.alpha = alpha_value;
            out.cpu_matmul.?.beta = beta_value;
            out.cpu_matmul.?.unary = null;
        }

        fn attachCpuUnaryDerived(out: *Self, pending: CpuMatmulFusion, unary_op: PendingUnary) void {
            if (comptime T != f32 and T != f64) return;
            if (!out.device.isCpu()) return;
            out.cpu_matmul = pending;
            out.cpu_matmul.?.unary = unary_op;
        }

        fn tryFuseCpuMatmulAdd(self: Self, other: Self, comptime op: fn (T, T) T) ArrayError!?Self {
            if (comptime T != f32 and T != f64) return null;
            const pending = self.cpu_matmul orelse return null;
            if (comptime op != opAdd and op != opSub) return null;
            if (!self.device.isCpu() or !other.device.isCpu()) return null;
            if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
            if (!other.isContiguous()) return null;
            var lhs_shape = [_]usize{ pending.lhs_shape[0], pending.lhs_shape[1] };
            var lhs_strides = [_]usize{ pending.lhs_shape[1], 1 };
            var rhs_shape = [_]usize{ pending.rhs_shape[0], pending.rhs_shape[1] };
            var rhs_strides = [_]usize{ pending.rhs_shape[1], 1 };
            const lhs_array = Self{
                .allocator = self.allocator,
                .data = pending.lhs_data,
                .shape = &lhs_shape,
                .strides = &lhs_strides,
                .device = .cpu,
            };
            const rhs_array = Self{
                .allocator = self.allocator,
                .data = pending.rhs_data,
                .shape = &rhs_shape,
                .strides = &rhs_strides,
                .device = .cpu,
            };
            if (comptime op == opAdd) {
                if (comptime T == f32) {
                    if (try axiom_cpu_backend.tryMatmulAddF32(lhs_array, rhs_array, other)) |out_value| {
                        var out = out_value;
                        out.attachCpuMatmulDerived(pending, 1.0, 1.0);
                        return out;
                    }
                } else {
                    if (try axiom_cpu_backend.tryMatmulAddF64(lhs_array, rhs_array, other)) |out_value| {
                        var out = out_value;
                        out.attachCpuMatmulDerived(pending, 1.0, 1.0);
                        return out;
                    }
                }
            } else {
                var neg_addend = try other.neg();
                defer neg_addend.deinit();
                if (comptime T == f32) {
                    if (try axiom_cpu_backend.tryMatmulAddF32(lhs_array, rhs_array, neg_addend)) |out_value| {
                        var out = out_value;
                        out.attachCpuMatmulDerived(pending, 1.0, -1.0);
                        return out;
                    }
                } else {
                    if (try axiom_cpu_backend.tryMatmulAddF64(lhs_array, rhs_array, neg_addend)) |out_value| {
                        var out = out_value;
                        out.attachCpuMatmulDerived(pending, 1.0, -1.0);
                        return out;
                    }
                }
            }
            return null;
        }

        fn tryFuseCpuMatmulRSub(self: Self, other: Self) ArrayError!?Self {
            if (comptime T != f32 and T != f64) return null;
            const pending = self.cpu_matmul orelse return null;
            if (!self.device.isCpu() or !other.device.isCpu()) return null;
            if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
            if (!other.isContiguous()) return null;
            var lhs_shape = [_]usize{ pending.lhs_shape[0], pending.lhs_shape[1] };
            var lhs_strides = [_]usize{ pending.lhs_shape[1], 1 };
            var rhs_shape = [_]usize{ pending.rhs_shape[0], pending.rhs_shape[1] };
            var rhs_strides = [_]usize{ pending.rhs_shape[1], 1 };
            const lhs_array = Self{
                .allocator = self.allocator,
                .data = pending.lhs_data,
                .shape = &lhs_shape,
                .strides = &lhs_strides,
                .device = .cpu,
            };
            const rhs_array = Self{
                .allocator = self.allocator,
                .data = pending.rhs_data,
                .shape = &rhs_shape,
                .strides = &rhs_strides,
                .device = .cpu,
            };
            if (comptime T == f32) {
                if (try axiom_cpu_backend.tryMatmulAddScaledF32(lhs_array, rhs_array, other, -1.0, 1.0)) |out_value| {
                    var out = out_value;
                    out.attachCpuMatmulDerived(pending, -1.0, 1.0);
                    return out;
                }
            } else {
                if (try axiom_cpu_backend.tryMatmulAddScaledF64(lhs_array, rhs_array, other, -1.0, 1.0)) |out_value| {
                    var out = out_value;
                    out.attachCpuMatmulDerived(pending, -1.0, 1.0);
                    return out;
                }
            }
            return null;
        }

        fn binaryArray(self: Self, other: Self, comptime op: fn (T, T) T) ArrayError!Self {
            if (!self.device.sameDevice(other.device)) return error.InvalidDevice;
            if (try self.tryFusePendingMatmulAdd(other, op)) |out| return out;
            if (try self.tryFuseCpuMatmulAdd(other, op)) |out| return out;
            if (comptime op == opAdd) {
                if (try other.tryFusePendingMatmulAdd(self, op)) |out| return out;
                if (try other.tryFuseCpuMatmulAdd(self, op)) |out| return out;
            } else if (comptime op == opSub) {
                if (try other.tryFusePendingMatmulRSub(self)) |out| return out;
                if (try other.tryFuseCpuMatmulRSub(self)) |out| return out;
            }
            if (self.pending_matmul != null) {
                var materialized = try self.materializePendingMatmul();
                defer materialized.deinit();
                return materialized.binaryArray(other, op);
            }
            if (other.pending_matmul != null) {
                var materialized_other = try other.materializePendingMatmul();
                defer materialized_other.deinit();
                return self.binaryArray(materialized_other, op);
            }
            if (self.device.isCuda()) {
                if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
                if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return error.TypeUnsupported;
                const maybe_op: ?axiom_cuda_backend.BinaryOp = if (comptime op == opAdd)
                    axiom_cuda_backend.BinaryOp.add
                else if (comptime op == opSub)
                    axiom_cuda_backend.BinaryOp.sub
                else if (comptime op == opMul)
                    axiom_cuda_backend.BinaryOp.mul
                else if (comptime op == opDiv)
                    axiom_cuda_backend.BinaryOp.div
                else
                    null;
                if (maybe_op) |op_value| {
                    if (comptime T == f32) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF32(op_value, self, other)) |out| return out;
                    } else if (comptime T == f64) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF64(op_value, self, other)) |out| return out;
                    } else if (comptime T == f16) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF16(op_value, self, other)) |out| return out;
                    } else if (comptime T == BFloat16) {
                        if (try axiom_cuda_backend.tryDeviceBinaryBF16(op_value, self, other)) |out| return out;
                    }
                    return error.BackendFailure;
                }
                return error.TypeUnsupported;
            }
            if (comptime T == f32 or T == f64 or T == f16 or T == BFloat16) {
                if (std.mem.eql(usize, self.shape, other.shape)) {
                    const maybe_op: ?axiom_backend.ElementwiseOp = if (comptime op == opAdd)
                        axiom_backend.ElementwiseOp.add
                    else if (comptime op == opSub)
                        axiom_backend.ElementwiseOp.sub
                    else if (comptime op == opMul)
                        axiom_backend.ElementwiseOp.mul
                    else if (comptime op == opDiv)
                        axiom_backend.ElementwiseOp.div
                    else
                        null;
                    if (maybe_op) |op_value| return try axiom_backend.elementwise(T, op_value, .prefer_axiom_cpu, self, other);
                }
            }
            if (std.mem.eql(usize, self.shape, other.shape)) {
                const out = try Self.empty(self.allocator, self.shape);
                if (binaryArraySimd(out.data, self.data, other.data, op)) return out;
                for (self.data, other.data, out.data) |lhs, rhs, *slot| {
                    slot.* = op(lhs, rhs);
                }
                return out;
            }
            if (comptime T == f32 or T == f64 or T == f16 or T == BFloat16) {
                if (true) {
                    const maybe_op: ?axiom_backend.ElementwiseOp = if (comptime op == opAdd)
                        axiom_backend.ElementwiseOp.add
                    else if (comptime op == opSub)
                        axiom_backend.ElementwiseOp.sub
                    else if (comptime op == opMul)
                        axiom_backend.ElementwiseOp.mul
                    else if (comptime op == opDiv)
                        axiom_backend.ElementwiseOp.div
                    else
                        null;
                    const accelerated = if (maybe_op) |op_value|
                        try axiom_backend.tryElementwiseScalarBroadcast(T, op_value, .prefer_axiom_cpu, self, other)
                    else
                        null;
                    if (accelerated) |out| return out;
                }
            }
            const out_shape = try computeBroadcastShape(self.allocator, self.shape, other.shape);
            defer self.allocator.free(out_shape);
            const out = try Self.empty(self.allocator, out_shape);

            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);

            for (out.data, 0..) |*slot, i| {
                unravelIndexInto(i, out_shape, out_multi);
                const ai = broadcastOffset(out_multi, out_shape.len, self.shape, self.strides);
                const bi = broadcastOffset(out_multi, out_shape.len, other.shape, other.strides);
                slot.* = op(self.data[ai], other.data[bi]);
            }
            return out;
        }

        fn binaryArrayPromote(
            self: Self,
            comptime U: type,
            other: Array(U),
            comptime P: type,
            comptime op: fn (P, P) P,
        ) ArrayError!Array(P) {
            if (std.mem.eql(usize, self.shape, other.shape)) {
                const out = try Array(P).empty(self.allocator, self.shape);
                for (self.data, other.data, out.data) |lhs, rhs, *slot| {
                    slot.* = op(castValue(P, lhs), castValue(P, rhs));
                }
                return out;
            }
            var lhs = try self.astype(P);
            defer lhs.deinit();
            var rhs = try other.astype(P);
            defer rhs.deinit();
            return lhs.binaryArray(rhs, op);
        }

        fn binaryScalarOut(self: Self, scalar: T, out: Self, comptime op: fn (T, T) T) ArrayError!void {
            if (!std.mem.eql(usize, out.shape, self.shape)) return error.ShapeMismatch;
            if (binaryScalarSimd(out.data, self.data, scalar, op)) return;
            for (self.data, out.data) |v, *slot| slot.* = op(v, scalar);
        }

        fn binaryScalar(self: Self, scalar: T, comptime op: fn (T, T) T) ArrayError!Self {
            if (self.device.isCuda()) {
                if (self.pending_matmul != null) {
                    if (try self.tryScalePendingMatmul(scalar, op)) |out| return out;
                    var materialized = try self.materializePendingMatmul();
                    defer materialized.deinit();
                    return materialized.binaryScalar(scalar, op);
                }
                if (comptime T != f32 and T != f64 and T != f16 and T != BFloat16) return error.TypeUnsupported;
                const maybe_op: ?axiom_cuda_backend.BinaryOp = if (comptime op == opAdd)
                    axiom_cuda_backend.BinaryOp.add
                else if (comptime op == opSub)
                    axiom_cuda_backend.BinaryOp.sub
                else if (comptime op == opMul)
                    axiom_cuda_backend.BinaryOp.mul
                else if (comptime op == opDiv)
                    axiom_cuda_backend.BinaryOp.div
                else
                    null;
                if (maybe_op) |op_value| {
                    var scalar_array = try Self.fullOn(self.allocator, self.shape, scalar, self.device);
                    defer scalar_array.deinit();
                    if (comptime T == f32) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF32(op_value, self, scalar_array)) |out| return out;
                    } else if (comptime T == f64) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF64(op_value, self, scalar_array)) |out| return out;
                    } else if (comptime T == f16) {
                        if (try axiom_cuda_backend.tryDeviceBinaryF16(op_value, self, scalar_array)) |out| return out;
                    } else if (comptime T == BFloat16) {
                        if (try axiom_cuda_backend.tryDeviceBinaryBF16(op_value, self, scalar_array)) |out| return out;
                    }
                    return error.BackendFailure;
                }
                return error.TypeUnsupported;
            }
            const out = try Self.empty(self.allocator, self.shape);
            if (binaryScalarSimd(out.data, self.data, scalar, op)) return out;
            for (self.data, out.data) |v, *slot| slot.* = op(v, scalar);
            return out;
        }

        fn ternaryArray(self: Self, second: Self, third: Self, comptime op: fn (T, T, T) T) ArrayError!Self {
            const tmp_shape = try computeBroadcastShape(self.allocator, self.shape, second.shape);
            defer self.allocator.free(tmp_shape);
            const out_shape = try computeBroadcastShape(self.allocator, tmp_shape, third.shape);
            defer self.allocator.free(out_shape);
            const out = try Self.empty(self.allocator, out_shape);
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            for (out.data, 0..) |*slot, i| {
                unravelIndexInto(i, out_shape, out_multi);
                const ai = broadcastOffset(out_multi, out_shape.len, self.shape, self.strides);
                const bi = broadcastOffset(out_multi, out_shape.len, second.shape, second.strides);
                const ci = broadcastOffset(out_multi, out_shape.len, third.shape, third.strides);
                slot.* = op(self.data[ai], second.data[bi], third.data[ci]);
            }
            return out;
        }

        fn ternaryArrayScalar(self: Self, second: Self, third: Self, scalar: T, comptime op: fn (T, T, T, T) T) ArrayError!Self {
            const tmp_shape = try computeBroadcastShape(self.allocator, self.shape, second.shape);
            defer self.allocator.free(tmp_shape);
            const out_shape = try computeBroadcastShape(self.allocator, tmp_shape, third.shape);
            defer self.allocator.free(out_shape);
            const out = try Self.empty(self.allocator, out_shape);
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            for (out.data, 0..) |*slot, i| {
                unravelIndexInto(i, out_shape, out_multi);
                const ai = broadcastOffset(out_multi, out_shape.len, self.shape, self.strides);
                const bi = broadcastOffset(out_multi, out_shape.len, second.shape, second.strides);
                const ci = broadcastOffset(out_multi, out_shape.len, third.shape, third.strides);
                slot.* = op(self.data[ai], second.data[bi], third.data[ci], scalar);
            }
            return out;
        }

        fn binaryArrayScalar(self: Self, other: Self, scalar: T, comptime op: fn (T, T, T) T) ArrayError!Self {
            const out_shape = try computeBroadcastShape(self.allocator, self.shape, other.shape);
            defer self.allocator.free(out_shape);
            const out = try Self.empty(self.allocator, out_shape);
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            for (out.data, 0..) |*slot, i| {
                unravelIndexInto(i, out_shape, out_multi);
                const ai = broadcastOffset(out_multi, out_shape.len, self.shape, self.strides);
                const bi = broadcastOffset(out_multi, out_shape.len, other.shape, other.strides);
                slot.* = op(self.data[ai], other.data[bi], scalar);
            }
            return out;
        }

        fn unary(self: Self, comptime op: fn (T) T) ArrayError!Self {
            const out = try Self.empty(self.allocator, self.shape);
            for (self.data, out.data) |v, *slot| slot.* = op(v);
            return out;
        }

        fn unaryBool(self: Self, comptime op: fn (T) bool) ArrayError!Array(bool) {
            const out = try Array(bool).empty(self.allocator, self.shape);
            for (self.data, out.data) |v, *slot| slot.* = op(v);
            return out;
        }

        fn opAdd(a: T, b: T) T {
            return addValue(T, a, b);
        }
        fn opSub(a: T, b: T) T {
            return subValue(T, a, b);
        }
        fn opMul(a: T, b: T) T {
            return mulValue(T, a, b);
        }
        fn opDiv(a: T, b: T) T {
            return divValue(T, a, b);
        }
        fn opPow(a: T, b: T) T {
            if (comptime isComplex(T)) return std.math.complex.pow(a, b);
            return std.math.pow(T, a, b);
        }
        fn opFloorDiv(a: T, b: T) T {
            return @divFloor(a, b);
        }
        fn opMod(a: T, b: T) T {
            return @mod(a, b);
        }
        fn opHypot(a: T, b: T) T {
            return std.math.hypot(a, b);
        }
        fn opAtan2(a: T, b: T) T {
            return std.math.atan2(a, b);
        }
        fn opNextAfter(a: T, b: T) T {
            return std.math.nextAfter(T, a, b);
        }
        fn opCopysign(a: T, b: T) T {
            return std.math.copysign(a, b);
        }
        fn opHeaviside(a: T, b: T) T {
            return if (a < zero(T)) zero(T) else if (a > zero(T)) one(T) else b;
        }
        fn opLogAddExp(a: T, b: T) T {
            if (comptime T == BFloat16) {
                const lhs = a.toF32();
                const rhs = b.toF32();
                const max_value = @max(lhs, rhs);
                return BFloat16.fromF32(max_value + std.math.log1p(std.math.exp(-@abs(lhs - rhs))));
            }
            const max_value = @max(a, b);
            return max_value + std.math.log1p(std.math.exp(-@abs(a - b)));
        }
        fn opLogAddExp2(a: T, b: T) T {
            if (comptime T == BFloat16) {
                const lhs = a.toF32();
                const rhs = b.toF32();
                const max_value = @max(lhs, rhs);
                return BFloat16.fromF32(max_value + std.math.log2(@as(f32, 1) + std.math.pow(f32, 2, -@abs(lhs - rhs))));
            }
            const max_value = @max(a, b);
            return max_value + std.math.log2(one(T) + std.math.pow(T, castValue(T, 2), -@abs(a - b)));
        }
        fn opXlogy(a: T, b: T) T {
            return if (a == zero(T)) zero(T) else a * std.math.log(T, std.math.e, b);
