        fn opLerpScalar(a: T, b: T, weight: T) T {
            return opLerp(a, b, weight);
        }
        fn opAddcmul(a: T, b: T, c: T, value: T) T {
            return addValue(T, a, mulValue(T, value, mulValue(T, b, c)));
