            ensureNumeric(T);
            const out = try Self.empty(self.allocator, self.shape);
            for (self.data, out.data) |value, *slot| {
                slot.* = if (value > zero(T)) value else mulValue(T, value, negative_slope);
            }
            return out;
        }

