        pub fn gelu(self: Self) ArrayError!Self {
            ensureFloat(T);
            return self.unary(struct {
                fn f(a: T) T {
                    const cubic = a * a * a;
                    const gelu_arg = castValue(T, @sqrt(2.0 / std.math.pi)) * (a + castValue(T, 0.044715) * cubic);
                    return castValue(T, 0.5) * a * (one(T) + std.math.tanh(gelu_arg));
                }
            }.f);
        }

