        pub fn isReal(self: Self) ArrayError!Array(bool) {
            var out = try Array(bool).empty(self.allocator, self.shape);
            errdefer out.deinit();
            if (comptime isComplex(T)) {
                for (self.data, out.data) |value, *slot| slot.* = value.im == 0;
            } else {
                @memset(out.data, true);
            }
            return out;
        }

        pub fn isreal(self: Self) ArrayError!Array(bool) {
            return self.isReal();
