        pub fn min(self: Self, axis_opt: ?isize, keepdims: bool) ArrayError!Self {
            ensureNumeric(T);
            if (self.data.len == 0) return error.EmptyArray;
            return self.reduceFirst(axis_opt, keepdims, struct {
                fn f(a: T, b: T) T {
                    return if (lessValue(T, b, a)) b else a;
                }
            }.f);
        }

