        fn reducedShape(self: Self, axis: usize, keepdims: bool) ArrayError![]usize {
            var out_shape = try self.allocator.alloc(usize, if (keepdims) self.shape.len else self.shape.len - 1);
            if (keepdims) {
                @memcpy(out_shape, self.shape);
                out_shape[axis] = 1;
            } else {
                for (self.shape[0..axis], 0..) |d, i| out_shape[i] = d;
                for (self.shape[axis + 1 ..], axis..) |d, i| out_shape[i] = d;
            }
            return out_shape;
        }

        fn mapReducedToInput(self: Self, axis: usize, keepdims: bool, out_multi: []const usize, in_multi: []usize) void {
            _ = self;
            if (keepdims) {
                @memcpy(in_multi, out_multi);
            } else {
                for (out_multi[0..axis], 0..) |coord, i| in_multi[i] = coord;
                for (out_multi[axis..], axis + 1..) |coord, i| in_multi[i] = coord;
            }
        }

        fn reduceFirst(self: Self, axis_opt: ?isize, keepdims: bool, comptime op: fn (T, T) T) ArrayError!Self {
            if (self.data.len == 0) return error.EmptyArray;
            if (axis_opt == null) {
                var total = self.data[0];
                for (self.data[1..]) |v| total = op(total, v);
                if (keepdims) {
                    const out_shape = try keepDimsAllOnes(self.allocator, self.shape.len);
                    defer self.allocator.free(out_shape);
                    return Self.fromSlice(self.allocator, &.{total}, out_shape);
                }
                return Self.fromSlice(self.allocator, &.{total}, &.{});
            }

            const axis = try normalizeDim(axis_opt.?, self.shape.len);
            if (self.shape[axis] == 0) return error.EmptyArray;
            const out_shape = try self.reducedShape(axis, keepdims);
            defer self.allocator.free(out_shape);
            var out = try Self.empty(self.allocator, out_shape);
            errdefer out.deinit();
            if (out.data.len == 0) return out;
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            var in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);

            for (out.data, 0..) |*slot, flat| {
                unravelIndexInto(flat, out_shape, out_multi);
                self.mapReducedToInput(axis, keepdims, out_multi, in_multi);
                in_multi[axis] = 0;
                var acc = self.data[ravelIndex(in_multi, self.strides)];
                for (1..self.shape[axis]) |axis_i| {
                    in_multi[axis] = axis_i;
                    acc = op(acc, self.data[ravelIndex(in_multi, self.strides)]);
                }
                slot.* = acc;
            }
            return out;
        }

        fn reduce(self: Self, axis_opt: ?isize, keepdims: bool, init_value: T, comptime op: fn (T, T) T) ArrayError!Self {
            if (axis_opt == null) {
                if (comptime op == opAdd) return self.scalarReductionResult(self.sumFlatValue(), keepdims);
                var total = init_value;
                for (self.data) |v| total = op(total, v);
                if (keepdims) {
                    const out_shape = try keepDimsAllOnes(self.allocator, self.shape.len);
                    defer self.allocator.free(out_shape);
                    return Self.fromSlice(self.allocator, &.{total}, out_shape);
                }
                return Self.fromSlice(self.allocator, &.{total}, &.{});
            }

            const axis = try normalizeDim(axis_opt.?, self.shape.len);
            var out_shape = try self.allocator.alloc(usize, if (keepdims) self.shape.len else self.shape.len - 1);
            defer self.allocator.free(out_shape);
            if (keepdims) {
                @memcpy(out_shape, self.shape);
                out_shape[axis] = 1;
            } else {
                for (self.shape[0..axis], 0..) |d, i| out_shape[i] = d;
                for (self.shape[axis + 1 ..], axis..) |d, i| out_shape[i] = d;
            }

            var out = try Self.full(self.allocator, out_shape, init_value);
            if (out.data.len == 0) return out;
            var in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);
            var out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            const out_strides = out.strides;
            for (self.data, 0..) |v, flat| {
                unravelIndexInto(flat, self.shape, in_multi);
                if (keepdims) {
                    @memcpy(out_multi, in_multi);
                    out_multi[axis] = 0;
                } else {
                    for (in_multi[0..axis], 0..) |coord, i| out_multi[i] = coord;
                    for (in_multi[axis + 1 ..], axis..) |coord, i| out_multi[i] = coord;
                }
                const oi = ravelIndex(out_multi, out_strides);
                out.data[oi] = op(out.data[oi], v);
            }
            return out;
        }

        fn keepDimsAllOnes(allocator: std.mem.Allocator, rank_count: usize) ArrayError![]usize {
            const dims = try allocator.alloc(usize, rank_count);
            @memset(dims, 1);
            return dims;
        }

        pub fn mean(self: Self, axis_opt: ?isize, keepdims: bool) ArrayError!Self {
            ensureFloat(T);
            if (axis_opt == null) {
                const result = self.sumFlatValue() / castValue(T, self.data.len);
                return self.scalarReductionResult(result, keepdims);
            }
            const out = try self.sum(axis_opt, keepdims);
            const divisor: T = if (axis_opt) |d| castValue(T, self.shape[try normalizeDim(d, self.shape.len)]) else castValue(T, self.data.len);
            for (out.data) |*v| v.* /= divisor;
            return out;
        }

        pub fn meanAxes(self: Self, axes: []const isize, keepdims: bool) ArrayError!Self {
            ensureFloat(T);
            return self.reduceAxes(axes, keepdims, Self.mean);
        }

        pub fn mean_axes(self: Self, axes: []const isize, keepdims: bool) ArrayError!Self {
            return self.meanAxes(axes, keepdims);
        }

        pub fn meanDim(self: Self, dim_opt: ?isize, keepdim: bool) ArrayError!Self {
            return self.mean(dim_opt, keepdim);
        }

        pub fn mean_dim(self: Self, dim_opt: ?isize, keepdim: bool) ArrayError!Self {
            return self.meanDim(dim_opt, keepdim);
        }

        pub fn meanDims(self: Self, dims: []const isize, keepdim: bool) ArrayError!Self {
            return self.meanAxes(dims, keepdim);
        }

        pub fn mean_dims(self: Self, dims: []const isize, keepdim: bool) ArrayError!Self {
            return self.meanDims(dims, keepdim);
        }

        pub fn variance(self: Self, axis_opt: ?isize, keepdims: bool, correction: T) ArrayError!Self {
            ensureFloat(T);
            if (axis_opt != null) {
                const axis = try normalizeDim(axis_opt.?, self.shape.len);
                const n = self.shape[axis];
                if (n == 0) return error.EmptyArray;
                var mean_t = try self.mean(axis_opt, true);
                defer mean_t.deinit();
                var out_shape = try self.allocator.alloc(usize, if (keepdims) self.shape.len else self.shape.len - 1);
                defer self.allocator.free(out_shape);
                if (keepdims) {
                    @memcpy(out_shape, self.shape);
                    out_shape[axis] = 1;
                } else {
                    for (self.shape[0..axis], 0..) |d, i| out_shape[i] = d;
                    for (self.shape[axis + 1 ..], axis..) |d, i| out_shape[i] = d;
                }
                var out = try Self.zeros(self.allocator, out_shape);
                var in_multi = try self.allocator.alloc(usize, self.shape.len);
                defer self.allocator.free(in_multi);
                var out_multi = try self.allocator.alloc(usize, out_shape.len);
                defer self.allocator.free(out_multi);
                var mean_multi = try self.allocator.alloc(usize, self.shape.len);
                defer self.allocator.free(mean_multi);
                for (self.data, 0..) |v, flat| {
                    unravelIndexInto(flat, self.shape, in_multi);
                    @memcpy(mean_multi, in_multi);
                    mean_multi[axis] = 0;
                    if (keepdims) {
                        @memcpy(out_multi, in_multi);
                        out_multi[axis] = 0;
                    } else {
                        for (in_multi[0..axis], 0..) |coord, i| out_multi[i] = coord;
                        for (in_multi[axis + 1 ..], axis..) |coord, i| out_multi[i] = coord;
                    }
                    const delta = v - mean_t.data[ravelIndex(mean_multi, mean_t.strides)];
                    const oi = ravelIndex(out_multi, out.strides);
                    out.data[oi] += delta * delta;
                }
                const denom = castValue(T, n) - correction;
                for (out.data) |*v| v.* /= denom;
                return out;
            }

            if (self.data.len == 0) return error.EmptyArray;
            var mean_value: T = zero(T);
            for (self.data) |v| mean_value += v;
            mean_value /= castValue(T, self.data.len);
            var total: T = zero(T);
            for (self.data) |v| {
                const delta = v - mean_value;
                total += delta * delta;
            }
            const denom = castValue(T, self.data.len) - correction;
            const result = total / denom;
            if (keepdims) {
                const out_shape = try keepDimsAllOnes(self.allocator, self.shape.len);
                defer self.allocator.free(out_shape);
                return Self.fromSlice(self.allocator, &.{result}, out_shape);
            }
            return Self.fromSlice(self.allocator, &.{result}, &.{});
        }

        pub fn var_(self: Self, axis_opt: ?isize, keepdims: bool, correction: T) ArrayError!Self {
            return self.variance(axis_opt, keepdims, correction);
        }

        pub fn varianceAxes(self: Self, axes: []const isize, keepdims: bool, correction: T) ArrayError!Self {
            ensureFloat(T);
            if (axes.len == 0) return self.clone();
            const normalized_axes = try normalizeUniqueAxes(self.allocator, axes, self.shape.len);
            defer self.allocator.free(normalized_axes);
            var reduce_mask = try self.allocator.alloc(bool, self.shape.len);
            defer self.allocator.free(reduce_mask);
            @memset(reduce_mask, false);
            const reduce_shape = try self.allocator.alloc(usize, normalized_axes.len);
            defer self.allocator.free(reduce_shape);
            var reduce_count: usize = 1;
            for (normalized_axes, 0..) |axis, i| {
                reduce_mask[axis] = true;
                if (self.shape[axis] == 0) return error.EmptyArray;
                reduce_shape[i] = self.shape[axis];
                reduce_count = std.math.mul(usize, reduce_count, self.shape[axis]) catch return error.InvalidShape;
            }

            const out_shape = try self.allocator.alloc(usize, if (keepdims) self.shape.len else self.shape.len - normalized_axes.len);
            defer self.allocator.free(out_shape);
            if (keepdims) {
                @memcpy(out_shape, self.shape);
                for (normalized_axes) |axis| out_shape[axis] = 1;
            } else {
                var write: usize = 0;
                for (self.shape, 0..) |extent, axis| {
                    if (reduce_mask[axis]) continue;
                    out_shape[write] = extent;
                    write += 1;
                }
            }

            var means = try self.meanAxes(axes, keepdims);
            defer means.deinit();
            var out = try Self.zeros(self.allocator, out_shape);
            errdefer out.deinit();
            if (out.data.len == 0) return out;

            const in_multi = try self.allocator.alloc(usize, self.shape.len);
            defer self.allocator.free(in_multi);
            const out_multi = try self.allocator.alloc(usize, out_shape.len);
            defer self.allocator.free(out_multi);
            for (self.data, 0..) |value, flat| {
                unravelIndexInto(flat, self.shape, in_multi);
                if (keepdims) {
                    @memcpy(out_multi, in_multi);
                    for (normalized_axes) |axis| out_multi[axis] = 0;
                } else {
                    var write: usize = 0;
                    for (in_multi, 0..) |coord, axis| {
                        if (reduce_mask[axis]) continue;
                        out_multi[write] = coord;
                        write += 1;
                    }
                }
                const out_index = ravelIndex(out_multi, out.strides);
                const delta = value - means.data[ravelIndex(out_multi, means.strides)];
                out.data[out_index] += delta * delta;
            }
            const denom = castValue(T, reduce_count) - correction;
            for (out.data) |*value| value.* /= denom;
            return out;
        }

        pub fn variance_axes(self: Self, axes: []const isize, keepdims: bool, correction: T) ArrayError!Self {
            return self.varianceAxes(axes, keepdims, correction);
        }

        pub fn varAxes(self: Self, axes: []const isize, keepdims: bool, correction: T) ArrayError!Self {
            return self.varianceAxes(axes, keepdims, correction);
        }

        pub fn var_axes(self: Self, axes: []const isize, keepdims: bool, correction: T) ArrayError!Self {
            return self.varianceAxes(axes, keepdims, correction);
        }

        pub fn varianceDim(self: Self, dim_opt: ?isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.variance(dim_opt, keepdim, correction);
        }

        pub fn variance_dim(self: Self, dim_opt: ?isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varianceDim(dim_opt, keepdim, correction);
        }

        pub fn varDim(self: Self, dim_opt: ?isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.var_(dim_opt, keepdim, correction);
        }

        pub fn var_dim(self: Self, dim_opt: ?isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varDim(dim_opt, keepdim, correction);
        }

        pub fn varianceDims(self: Self, dims: []const isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varianceAxes(dims, keepdim, correction);
        }

        pub fn variance_dims(self: Self, dims: []const isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varianceDims(dims, keepdim, correction);
        }

        pub fn varDims(self: Self, dims: []const isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varAxes(dims, keepdim, correction);
        }

        pub fn var_dims(self: Self, dims: []const isize, keepdim: bool, correction: T) ArrayError!Self {
            return self.varDims(dims, keepdim, correction);
        }

        pub fn stddev(self: Self, axis_opt: ?isize, keepdims: bool, correction: T) ArrayError!Self {
            const out = try self.variance(axis_opt, keepdims, correction);
            for (out.data) |*v| v.* = std.math.sqrt(v.*);
            return out;
        }

        pub fn stddevAxes(self: Self, axes: []const isize, keepdims: bool, correction: T) ArrayError!Self {
            ensureFloat(T);
            const out = try self.varianceAxes(axes, keepdims, correction);
            for (out.data) |*value| value.* = std.math.sqrt(value.*);
            return out;
        }

