    defer nan_corr_view.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, nan_corr_view.shape);
    try std.testing.expectEqual(@as(usize, 5), try nan_stats_view.nanargmax());
    try std.testing.expectEqual(@as(usize, 0), try nan_stats_view.nanargmin());
    var nan_argmax_view = try nan_stats_view.nanargmaxAxis(0, false);
    defer nan_argmax_view.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 1, 2 }, nan_argmax_view.data);
    var nan_argmin_view = try nan_stats_view.nanargminAxis(1, false);
    defer nan_argmin_view.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 0, 0, 1 }, nan_argmin_view.data);
    var pow_scalar_view = try stepped.powScalar(2);
    defer pow_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 900, 2500, 9801 }, pow_scalar_view.data);
    var floor_div_scalar_view = try stepped.floorDivScalar(4);
    defer floor_div_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 0, 7, 12, 24 }, floor_div_scalar_view.data);
    var mod_scalar_view = try stepped.modScalar(7);
    defer mod_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 2, 1, 1 }, mod_scalar_view.data);
    var max_scalar_view = try stepped.maximumScalar(10);
    defer max_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 10, 30, 50, 99 }, max_scalar_view.data);
    var min_scalar_view = try stepped.minimumScalar(10);
    defer min_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 10, 10, 10 }, min_scalar_view.data);
    var clip_min_view = try stepped.clipMin(10);
    defer clip_min_view.deinit();
    try std.testing.expectEqualSlices(f64, max_scalar_view.data, clip_min_view.data);
    var clamp_min_view = try stepped.clampMin(10);
    defer clamp_min_view.deinit();
    try std.testing.expectEqualSlices(f64, max_scalar_view.data, clamp_min_view.data);
    var clip_max_view = try stepped.clipMax(10);
    defer clip_max_view.deinit();
    try std.testing.expectEqualSlices(f64, min_scalar_view.data, clip_max_view.data);
    var clamp_max_view = try stepped.clampMax(10);
    defer clamp_max_view.deinit();
    try std.testing.expectEqualSlices(f64, min_scalar_view.data, clamp_max_view.data);
    var hypot_scalar_view = try stepped.hypotScalar(4);
    defer hypot_scalar_view.deinit();
    try std.testing.expectApproxEqAbs(std.math.sqrt(@as(f64, 17)), hypot_scalar_view.data[0], 1e-12);
    try std.testing.expectApproxEqAbs(std.math.sqrt(@as(f64, 916)), hypot_scalar_view.data[1], 1e-12);
    var atan2_scalar_view = try stepped.atan2Scalar(2);
    defer atan2_scalar_view.deinit();
    try std.testing.expectApproxEqAbs(std.math.atan2(@as(f64, 1), @as(f64, 2)), atan2_scalar_view.data[0], 1e-12);
    var arctan2_scalar_view = try stepped.arctan2Scalar(2);
    defer arctan2_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, atan2_scalar_view.data, arctan2_scalar_view.data);
    var next_scalar_view = try stepped.nextafterScalar(100);
    defer next_scalar_view.deinit();
    try std.testing.expect(next_scalar_view.data[0] > stepped.data[0]);
    var copysign_scalar_view = try stepped.copysignScalar(-1);
    defer copysign_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ -1, -30, -50, -99 }, copysign_scalar_view.data);
    var bool_source = try Array(bool).fromSlice(gpa, &.{
        true,  false, true,  false,
        false, true,  false, true,
    }, &.{ 2, 4 });
    defer bool_source.deinit();
    var bool_lhs = try bool_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer bool_lhs.deinit();
    var bool_rhs_source = try Array(bool).fromSlice(gpa, &.{ true, false }, &.{ 1, 2 });
    defer bool_rhs_source.deinit();
    var bool_rhs = try bool_rhs_source.asView();
    defer bool_rhs.deinit();
    var logical_and_view = try bool_lhs.logicalAnd(bool_rhs);
    defer logical_and_view.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, false, false }, logical_and_view.data);
    var logical_or_view = try bool_lhs.logicalOr(bool_rhs);
    defer logical_or_view.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, true, true, false }, logical_or_view.data);
    var logical_xor_view = try bool_lhs.logicalXor(bool_rhs);
    defer logical_xor_view.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, true, true, false }, logical_xor_view.data);
    var logical_not_view = try bool_lhs.logicalNot();
    defer logical_not_view.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, true, true }, logical_not_view.data);

    var predicate_source = try Array(f64).fromSlice(gpa, &.{
        -1.0, std.math.nan(f64), 0.0,                    std.math.inf(f64),
        -0.0, 2.0,               std.math.floatMin(f64), -std.math.inf(f64),
    }, &.{ 2, 4 });
    defer predicate_source.deinit();
    var predicate_view = try predicate_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer predicate_view.deinit();
    var sign_bits = try predicate_view.signbit();
    defer sign_bits.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, true, false }, sign_bits.data);
    var nan_mask = try predicate_view.isNan();
    defer nan_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false }, nan_mask.data);
    var inf_mask = try predicate_view.isInf();
    defer inf_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false }, inf_mask.data);
    var finite_mask = try predicate_view.isFinite();
    defer finite_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, true, true, true }, finite_mask.data);
    var normal_mask = try predicate_view.isNormal();
    defer normal_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, false, true }, normal_mask.data);
    var predicate_full_view = try predicate_source.asView();
    defer predicate_full_view.deinit();
    var pos_inf_mask = try predicate_full_view.isPosInf();
    defer pos_inf_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, true, false, false, false, false }, pos_inf_mask.data);
    var neg_inf_mask = try predicate_full_view.isNegInf();
    defer neg_inf_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false, false, false, false, true }, neg_inf_mask.data);

    var heaviside_source = try Array(f64).fromSlice(gpa, &.{ -1, 0, 2, 0 }, &.{ 2, 2 });
    defer heaviside_source.deinit();
    var heaviside_view = try heaviside_source.asView();
    defer heaviside_view.deinit();
    var heaviside_scalar_view = try heaviside_view.heavisideScalar(0.25);
    defer heaviside_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 0, 0.25, 1, 0.25 }, heaviside_scalar_view.data);
    var ldexp_scalar_view = try stepped.ldexpScalar(1);
    defer ldexp_scalar_view.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 2, 60, 100, 198 }, ldexp_scalar_view.data);
    var bad_rhs = try Array(f64).fromSlice(gpa, &.{ 1, 2, 3 }, &.{3});
    defer bad_rhs.deinit();
    var bad_rhs_view = try bad_rhs.asView();
    defer bad_rhs_view.deinit();
    try std.testing.expectError(error.ShapeMismatch, stepped.maximum(bad_rhs_view));

    var replacement = try Array(f64).fromSlice(gpa, &.{ 7, 8 }, &.{ 1, 2 });
    defer replacement.deinit();
    try stepped.copyFromArray(replacement);
    try std.testing.expectEqual(@as(f64, 7), a.data[0]);
    try std.testing.expectEqual(@as(f64, 8), a.data[2]);
    try std.testing.expectEqual(@as(f64, 7), a.data[4]);
    try std.testing.expectEqual(@as(f64, 8), a.data[6]);

    try narrowed.fill(-1);
    try std.testing.expectEqualSlices(f64, &.{ 7, -1, -1, 4, 7, -1, -1, 80 }, a.data);
}

test "array view transcendental unary math is view aware" {
    const gpa = std.testing.allocator;

    var positive_source = try Array(f64).fromSlice(gpa, &.{ 0.25, 99, 0.5, 88, 1.25, 77, 2.0, 66 }, &.{ 2, 4 });
    defer positive_source.deinit();
    var positive = try positive_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer positive.deinit();
    try std.testing.expect(!positive.isContiguous());
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).exp, Array(f64).exp, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).exp2, Array(f64).exp2, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).expm1, Array(f64).expm1, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).log, Array(f64).log, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).log2, Array(f64).log2, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).log10, Array(f64).log10, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).log1p, Array(f64).log1p, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).lgamma, Array(f64).lgamma, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).sqrt, Array(f64).sqrt, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).rsqrt, Array(f64).rsqrt, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).cbrt, Array(f64).cbrt, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).deg2rad, Array(f64).deg2rad, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).rad2deg, Array(f64).rad2deg, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).sinc, Array(f64).sinc, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).sin, Array(f64).sin, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).cos, Array(f64).cos, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).tan, Array(f64).tan, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).sinh, Array(f64).sinh, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).cosh, Array(f64).cosh, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).tanh, Array(f64).tanh, 1e-12);
    try expectF64ViewUnaryMatchesArray(positive, ArrayView(f64).asinh, Array(f64).asinh, 1e-12);

    var fractional_source = try Array(f64).fromSlice(gpa, &.{ -1.25, 9, -0.5, 8, 1.5, 7, 2.75, 6 }, &.{ 2, 4 });
    defer fractional_source.deinit();
    var fractional = try fractional_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer fractional.deinit();
    try std.testing.expect(!fractional.isContiguous());
    try expectF64ViewUnaryMatchesArray(fractional, ArrayView(f64).floor, Array(f64).floor, 1e-12);
    try expectF64ViewUnaryMatchesArray(fractional, ArrayView(f64).ceil, Array(f64).ceil, 1e-12);
    try expectF64ViewUnaryMatchesArray(fractional, ArrayView(f64).round, Array(f64).round, 1e-12);
    try expectF64ViewUnaryMatchesArray(fractional, ArrayView(f64).trunc, Array(f64).trunc, 1e-12);

    var bounded_source = try Array(f64).fromSlice(gpa, &.{ -0.75, 9, -0.25, 8, 0.25, 7, 0.75, 6 }, &.{ 2, 4 });
    defer bounded_source.deinit();
    var bounded = try bounded_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer bounded.deinit();
    try std.testing.expect(!bounded.isContiguous());
    try expectF64ViewUnaryMatchesArray(bounded, ArrayView(f64).asin, Array(f64).asin, 1e-12);
    try expectF64ViewUnaryMatchesArray(bounded, ArrayView(f64).acos, Array(f64).acos, 1e-12);
    try expectF64ViewUnaryMatchesArray(bounded, ArrayView(f64).atan, Array(f64).atan, 1e-12);
    try expectF64ViewUnaryMatchesArray(bounded, ArrayView(f64).atanh, Array(f64).atanh, 1e-12);

    var acosh_source = try Array(f64).fromSlice(gpa, &.{ 1.0, 9, 1.25, 8, 2.0, 7, 3.0, 6 }, &.{ 2, 4 });
    defer acosh_source.deinit();
    var acosh_view = try acosh_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer acosh_view.deinit();
    try std.testing.expect(!acosh_view.isContiguous());
    try expectF64ViewUnaryMatchesArray(acosh_view, ArrayView(f64).acosh, Array(f64).acosh, 1e-12);

    var probability_source = try Array(f64).fromSlice(gpa, &.{ 0.2, 9, 0.4, 8, 0.6, 7, 0.8, 6 }, &.{ 2, 4 });
    defer probability_source.deinit();
    var probability = try probability_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer probability.deinit();
    try std.testing.expect(!probability.isContiguous());
    try expectF64ViewUnaryMatchesArray(probability, ArrayView(f64).logit, Array(f64).logit, 1e-12);
    try expectF64ViewUnaryMatchesArray(probability, ArrayView(f64).expit, Array(f64).expit, 1e-12);
    try expectF64ViewUnaryMatchesArray(probability, ArrayView(f64).sigmoid, Array(f64).sigmoid, 1e-12);

    var activation_source = try Array(f64).fromSlice(gpa, &.{ -2.0, 9, -0.5, 8, 0.0, 7, 3.0, 6 }, &.{ 2, 4 });
    defer activation_source.deinit();
    var activation = try activation_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer activation.deinit();
    try std.testing.expect(!activation.isContiguous());
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).relu, Array(f64).relu, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).softplus, Array(f64).softplus, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).softsign, Array(f64).softsign, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).gelu, Array(f64).gelu, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).silu, Array(f64).silu, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).SiLU, Array(f64).SiLU, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).swish, Array(f64).swish, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).mish, Array(f64).mish, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).hardsigmoid, Array(f64).hardsigmoid, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).hardSigmoid, Array(f64).hardSigmoid, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).hardswish, Array(f64).hardswish, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).hardSwish, Array(f64).hardSwish, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).logsigmoid, Array(f64).logsigmoid, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).logSigmoid, Array(f64).logSigmoid, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).log_sigmoid, Array(f64).log_sigmoid, 1e-12);
    try expectF64ViewUnaryMatchesArray(activation, ArrayView(f64).relu6, Array(f64).relu6, 1e-12);

    var activation_owned = try activation.toArray();
    defer activation_owned.deinit();
    var expected_leaky = try activation_owned.leakyRelu(0.1);
    defer expected_leaky.deinit();
    var actual_leaky = try activation.leakyRelu(0.1);
    defer actual_leaky.deinit();
    try expectApproxEqualSlices(f64, expected_leaky.data, actual_leaky.data, 1e-12);
    var expected_elu = try activation_owned.elu(1.25);
    defer expected_elu.deinit();
    var actual_elu = try activation.elu(1.25);
    defer actual_elu.deinit();
    try expectApproxEqualSlices(f64, expected_elu.data, actual_elu.data, 1e-12);
    var expected_celu = try activation_owned.celu(1.25);
    defer expected_celu.deinit();
    var actual_celu = try activation.celu(1.25);
    defer actual_celu.deinit();
    try expectApproxEqualSlices(f64, expected_celu.data, actual_celu.data, 1e-12);
    var expected_hardtanh = try activation_owned.hardtanh(-0.75, 1.25);
    defer expected_hardtanh.deinit();
    var actual_hardtanh = try activation.hardTanh(-0.75, 1.25);
    defer actual_hardtanh.deinit();
    try expectApproxEqualSlices(f64, expected_hardtanh.data, actual_hardtanh.data, 1e-12);
    var expected_hardshrink = try activation_owned.hardshrink(0.75);
    defer expected_hardshrink.deinit();
    var actual_hardshrink = try activation.hardShrink(0.75);
    defer actual_hardshrink.deinit();
    try expectApproxEqualSlices(f64, expected_hardshrink.data, actual_hardshrink.data, 1e-12);
    var expected_softshrink = try activation_owned.softshrink(0.75);
    defer expected_softshrink.deinit();
    var actual_softshrink = try activation.softShrink(0.75);
    defer actual_softshrink.deinit();
    try expectApproxEqualSlices(f64, expected_softshrink.data, actual_softshrink.data, 1e-12);
    var expected_tanhshrink = try activation_owned.tanhshrink();
    defer expected_tanhshrink.deinit();
    var actual_tanhshrink = try activation.tanhShrink();
    defer actual_tanhshrink.deinit();
    try expectApproxEqualSlices(f64, expected_tanhshrink.data, actual_tanhshrink.data, 1e-12);

    var expected_clip = try activation_owned.clip(-0.25, 1.0);
    defer expected_clip.deinit();
    var actual_clip = try activation.clip(-0.25, 1.0);
    defer actual_clip.deinit();
    try expectApproxEqualSlices(f64, expected_clip.data, actual_clip.data, 1e-12);
}

test "array view scalar elementwise and logical wrappers are view aware" {
    const gpa = std.testing.allocator;

    var source = try Array(f64).fromSlice(gpa, &.{
        -2.0, 90.0, 0.5, 80.0,
        1.5,  70.0, 3.0, 60.0,
    }, &.{ 2, 4 });
    defer source.deinit();
    var view = try source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer view.deinit();
    try std.testing.expect(!view.isContiguous());
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).powScalar, Array(f64).powScalar, 2.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).floorDivScalar, Array(f64).floorDivScalar, 2.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).modScalar, Array(f64).modScalar, 2.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).maximumScalar, Array(f64).maximumScalar, 1.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).minimumScalar, Array(f64).minimumScalar, 1.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).hypotScalar, Array(f64).hypotScalar, 4.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).atan2Scalar, Array(f64).atan2Scalar, 2.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).copysignScalar, Array(f64).copysignScalar, -1.0, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).heavisideScalar, Array(f64).heavisideScalar, 0.25, 1e-12);
    try expectF64ViewScalarMatchesArray(view, ArrayView(f64).xlogyScalar, Array(f64).xlogyScalar, std.math.e, 1e-12);

    var positive_source = try Array(f64).fromSlice(gpa, &.{
        0.0, 90.0, 1.0, 80.0,
        2.0, 70.0, 3.0, 60.0,
    }, &.{ 2, 4 });
    defer positive_source.deinit();
    var positive_view = try positive_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer positive_view.deinit();
    try expectF64ViewScalarMatchesArray(positive_view, ArrayView(f64).logAddExpScalar, Array(f64).logAddExpScalar, 0.5, 1e-12);
    try expectF64ViewScalarMatchesArray(positive_view, ArrayView(f64).logAddExp2Scalar, Array(f64).logAddExp2Scalar, 0.5, 1e-12);

    var nan_source = try Array(f64).fromSlice(gpa, &.{ std.math.nan(f64), 90.0, 2.0, 80.0 }, &.{ 1, 4 });
    defer nan_source.deinit();
    var nan_view = try nan_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer nan_view.deinit();
    try expectF64ViewScalarMatchesArray(nan_view, ArrayView(f64).fmaxScalar, Array(f64).fmaxScalar, 1.0, 1e-12);
    try expectF64ViewScalarMatchesArray(nan_view, ArrayView(f64).fminScalar, Array(f64).fminScalar, 1.0, 1e-12);

    var next_source = try Array(f64).fromSlice(gpa, &.{ 1.0, 90.0, 2.0, 80.0 }, &.{ 1, 4 });
    defer next_source.deinit();
    var next_view = try next_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer next_view.deinit();
    var next_owned = try next_view.toArray();
    defer next_owned.deinit();
    var expected_next = try next_owned.nextAfterScalar(10.0);
    defer expected_next.deinit();
    var actual_next = try next_view.nextAfterScalar(10.0);
    defer actual_next.deinit();
    try std.testing.expectEqualSlices(f64, expected_next.data, actual_next.data);
    var expected_ldexp = try next_owned.ldexpScalar(2);
    defer expected_ldexp.deinit();
    var actual_ldexp = try next_view.ldexpScalar(2);
    defer actual_ldexp.deinit();
    try expectApproxEqualSlices(f64, expected_ldexp.data, actual_ldexp.data, 1e-12);

    var complex_source = try Array(Complex64).fromSlice(gpa, &.{
        Complex64.init(1, 0), Complex64.init(9, 9), Complex64.init(2, 3), Complex64.init(8, 8),
    }, &.{ 1, 4 });
    defer complex_source.deinit();
    var complex_view = try complex_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer complex_view.deinit();
    var real_mask = try complex_view.isReal();
    defer real_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false }, real_mask.data);
    var complex_mask = try complex_view.iscomplex();
    defer complex_mask.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, true }, complex_mask.data);

    var bool_source = try Array(bool).fromSlice(gpa, &.{
        true, false, false, true,
        true, true,  false, false,
    }, &.{ 2, 4 });
    defer bool_source.deinit();
    var bool_view = try bool_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer bool_view.deinit();
    var rhs = try Array(bool).fromSlice(gpa, &.{ true, false }, &.{ 1, 2 });
    defer rhs.deinit();
    var and_array = try bool_view.logicalAndArray(rhs);
    defer and_array.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, true, false }, and_array.data);
    var or_array = try bool_view.logicalOrArray(rhs);
    defer or_array.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, true, false }, or_array.data);
    var xor_array = try bool_view.logicalXorArray(rhs);
    defer xor_array.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false }, xor_array.data);
    var and_scalar = try bool_view.logicalAndScalar(false);
    defer and_scalar.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false }, and_scalar.data);
    var or_scalar = try bool_view.logicalOrScalar(false);
    defer or_scalar.deinit();
    try std.testing.expectEqualSlices(bool, &.{ true, false, true, false }, or_scalar.data);
    var xor_scalar = try bool_view.logicalXorScalar(true);
    defer xor_scalar.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, true, false, true }, xor_scalar.data);
}

test "array view binary and fused elementwise wrappers are view aware" {
    const gpa = std.testing.allocator;

    var lhs_source = try Array(f64).fromSlice(gpa, &.{
        1.0, 90.0, 2.0, 80.0,
        3.0, 70.0, 4.0, 60.0,
    }, &.{ 2, 4 });
    defer lhs_source.deinit();
    var lhs = try lhs_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer lhs.deinit();
    try std.testing.expect(!lhs.isContiguous());

    var rhs_source = try Array(f64).fromSlice(gpa, &.{ 2.0, 99.0, 3.0, 88.0 }, &.{ 1, 4 });
    defer rhs_source.deinit();
    var rhs = try rhs_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer rhs.deinit();
    try std.testing.expect(!rhs.isContiguous());

    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).pow, Array(f64).pow, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).floorDiv, Array(f64).floorDiv, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).mod, Array(f64).mod, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).maximum, Array(f64).maximum, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).minimum, Array(f64).minimum, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).hypot, Array(f64).hypot, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).atan2, Array(f64).atan2, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).nextAfter, Array(f64).nextAfter, 0.0);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).logAddExp, Array(f64).logAddExp, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).logAddExp2, Array(f64).logAddExp2, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, rhs, ArrayView(f64).xlogy, Array(f64).xlogy, 1e-12);

    var sign_source = try Array(f64).fromSlice(gpa, &.{ -1.0, 99.0, 1.0, 88.0 }, &.{ 1, 4 });
    defer sign_source.deinit();
    var sign_view = try sign_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer sign_view.deinit();
    try expectF64ViewBinaryMatchesArray(lhs, sign_view, ArrayView(f64).copysign, Array(f64).copysign, 1e-12);

    var heaviside_source = try Array(f64).fromSlice(gpa, &.{ -1.0, 90.0, 0.0, 80.0, 2.0, 70.0, 0.0, 60.0 }, &.{ 2, 4 });
    defer heaviside_source.deinit();
    var heaviside_view = try heaviside_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer heaviside_view.deinit();
    var zero_values_source = try Array(f64).fromSlice(gpa, &.{ 0.25, 99.0, 0.75, 88.0 }, &.{ 1, 4 });
    defer zero_values_source.deinit();
    var zero_values = try zero_values_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer zero_values.deinit();
    try expectF64ViewBinaryMatchesArray(heaviside_view, zero_values, ArrayView(f64).heaviside, Array(f64).heaviside, 1e-12);

    var nan_rhs_source = try Array(f64).fromSlice(gpa, &.{ std.math.nan(f64), 99.0, 2.5, 88.0 }, &.{ 1, 4 });
    defer nan_rhs_source.deinit();
    var nan_rhs = try nan_rhs_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer nan_rhs.deinit();
    try expectF64ViewBinaryMatchesArray(lhs, nan_rhs, ArrayView(f64).fmax, Array(f64).fmax, 1e-12);
    try expectF64ViewBinaryMatchesArray(lhs, nan_rhs, ArrayView(f64).fmin, Array(f64).fmin, 1e-12);

    var end_source = try Array(f64).fromSlice(gpa, &.{ 10.0, 90.0, 20.0, 80.0 }, &.{ 1, 4 });
    defer end_source.deinit();
    var end = try end_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer end.deinit();
    var weight_source = try Array(f64).fromSlice(gpa, &.{ 0.0, 99.0, 0.5, 88.0 }, &.{ 2, 2 });
    defer weight_source.deinit();
    var weight = try weight_source.sliceAxisView(1, .{ .start = 0, .stop = 2, .step = 2 });
    defer weight.deinit();
    try expectF64ViewTernaryMatchesArray(lhs, end, weight, ArrayView(f64).lerp, Array(f64).lerp, 1e-12);

    var lhs_owned = try lhs.toArray();
    defer lhs_owned.deinit();
    var end_owned = try end.toArray();
    defer end_owned.deinit();
    var expected_lerp_scalar = try lhs_owned.lerpScalar(end_owned, 0.25);
    defer expected_lerp_scalar.deinit();
    var actual_lerp_scalar = try lhs.lerpScalar(end, 0.25);
    defer actual_lerp_scalar.deinit();
    try expectApproxEqualSlices(f64, expected_lerp_scalar.data, actual_lerp_scalar.data, 1e-12);

    var input1_source = try Array(f64).fromSlice(gpa, &.{ 2.0, 99.0, 3.0, 88.0 }, &.{ 1, 4 });
    defer input1_source.deinit();
    var input1 = try input1_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer input1.deinit();
    var input2_source = try Array(f64).fromSlice(gpa, &.{ 5.0, 99.0, 7.0, 88.0 }, &.{ 1, 4 });
    defer input2_source.deinit();
    var input2 = try input2_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer input2.deinit();
    try expectF64ViewTernaryScalarMatchesArray(lhs, input1, input2, 0.5, ArrayView(f64).addcmul, Array(f64).addcmul, 1e-12);
    try expectF64ViewTernaryScalarMatchesArray(lhs, input1, input2, 2.0, ArrayView(f64).addcdiv, Array(f64).addcdiv, 1e-12);

    var lo_source = try Array(f64).fromSlice(gpa, &.{ 2.0, 99.0, 2.5, 88.0 }, &.{ 1, 4 });
    defer lo_source.deinit();
    var lo = try lo_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer lo.deinit();
    var hi_source = try Array(f64).fromSlice(gpa, &.{ 2.5, 99.0, 3.5, 88.0 }, &.{ 1, 4 });
    defer hi_source.deinit();
    var hi = try hi_source.sliceAxisView(1, .{ .start = 0, .stop = 4, .step = 2 });
    defer hi.deinit();
    var lo_owned = try lo.toArray();
    defer lo_owned.deinit();
    var hi_owned = try hi.toArray();
    defer hi_owned.deinit();
    var expected_clip = try lhs_owned.clipArray(lo_owned, hi_owned);
    defer expected_clip.deinit();
    var actual_clip = try lhs.clipArray(lo, hi);
    defer actual_clip.deinit();
    try expectApproxEqualSlices(f64, expected_clip.data, actual_clip.data, 1e-12);

    var bad_rhs = try Array(f64).fromSlice(gpa, &.{ 1.0, 2.0, 3.0 }, &.{3});
    defer bad_rhs.deinit();
    var bad_rhs_view = try bad_rhs.asView();
    defer bad_rhs_view.deinit();
    try std.testing.expectError(error.ShapeMismatch, lhs.maximum(bad_rhs_view));
    try std.testing.expectError(error.ShapeMismatch, lhs.lerp(end, bad_rhs_view));
}

test "array view object indexing wrappers" {
    const gpa = std.testing.allocator;
    var a = try Array(f64).fromSlice(gpa, &.{ 1, 0, 3, 4, 0, 6 }, &.{ 2, 3 });
    defer a.deinit();
    var view = try a.transposeView();
    defer view.deinit();

    var take_idx = try Array(usize).fromSlice(gpa, &.{ 0, 5, 2 }, &.{3});
    defer take_idx.deinit();
    var flat_take = try view.take(take_idx, null);
    defer flat_take.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 6, 0 }, flat_take.data);

    var signed_idx = try Array(isize).fromSlice(gpa, &.{ -1, 0 }, &.{2});
    defer signed_idx.deinit();
    var signed_take = try view.indexSelectSigned(0, signed_idx);
    defer signed_take.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, signed_take.shape);
    try std.testing.expectEqualSlices(f64, &.{ 3, 6, 1, 4 }, signed_take.data);

    var gather_idx = try Array(isize).fromSlice(gpa, &.{ -1, 0, 1, 0, -1, 1 }, &.{ 3, 2 });
    defer gather_idx.deinit();
    var gathered = try view.gatherSigned(1, gather_idx);
    defer gathered.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 4, 1, 0, 0, 6, 6 }, gathered.data);

    var mask = try Array(bool).fromSlice(gpa, &.{ true, false, false, true, true, false }, &.{ 3, 2 });
    defer mask.deinit();
    var masked = try view.maskedSelect(mask);
    defer masked.deinit();
    try std.testing.expectEqualSlices(f64, &.{ 1, 0, 3 }, masked.data);

    var rows = try Array(bool).fromSlice(gpa, &.{ true, false, true }, &.{3});
    defer rows.deinit();
    var compressed = try view.compress(rows, 0);
    defer compressed.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 2, 2 }, compressed.shape);
    try std.testing.expectEqualSlices(f64, &.{ 1, 4, 3, 6 }, compressed.data);

    try std.testing.expectEqual(@as(usize, 4), view.countNonzero());
    var nz = try view.nonzero();
    defer nz.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 4, 2 }, nz.shape);
    try std.testing.expectEqualSlices(usize, &.{ 0, 0, 0, 1, 2, 0, 2, 1 }, nz.data);

    var sorted_values = try Array(f64).fromSlice(gpa, &.{ 1, 2, 2, 4 }, &.{4});
    defer sorted_values.deinit();
    var sorted_view = try sorted_values.asStrided(&.{4}, &.{1}, 0);
    defer sorted_view.deinit();
    var probes = try Array(f64).fromSlice(gpa, &.{ 2, 3 }, &.{2});
    defer probes.deinit();
    var positions = try sorted_view.searchsorted(probes, .right);
    defer positions.deinit();
    try std.testing.expectEqualSlices(usize, &.{ 3, 3 }, positions.data);

    var needles = try Array(f64).fromSlice(gpa, &.{ 3, 6 }, &.{2});
    defer needles.deinit();
    var members = try view.isin(needles, false);
    defer members.deinit();
    try std.testing.expectEqualSlices(bool, &.{ false, false, false, false, true, true }, members.data);
}

test "array view object statistics wrappers" {
    const gpa = std.testing.allocator;
    const nan = std.math.nan(f64);
    var a = try Array(f64).fromSlice(gpa, &.{
        1, 2, nan,
        4, 5, 6,
    }, &.{ 2, 3 });
    defer a.deinit();
    var view = try a.transposeView();
    defer view.deinit();

    var sum0 = try view.sum(0, false);
